-- =============================================================================
-- 504 — LE CAHIER D'EXERCICES DE 2DE (partie 6)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 504 --niveau 2de --fichiers espagnol.n1,espagnol.n2,francais.n1 --suffixe 6 > supabase/contenu/504_exercices_2de_6.sql
--
-- 81 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   espagnol.n1             24 exercices · 8 chapitres
--   espagnol.n2             21 exercices · 7 chapitres
--   francais.n1             36 exercices · 12 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('794c4be9-76d7-57d8-990b-ad3c6a37a92b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le courriel de Marta à son correspondant","competence":"comprendre-langue","situation":"Marta écrit à Pablo, son correspondant français. Elle lui parle de sa journée, de la veille et de son enfance.","documents":[{"id":"correo","type":"texte","genre":"lettre","titre":"Correo de Marta","blocs":["Hola, Pablo:","Hoy he escrito mi primer correo en francés. Ayer comí en casa de mi abuela y por la tarde vimos una película.","Cuando era pequeña, mi abuela cocinaba paella todos los domingos."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui forment le *pretérito perfecto* dans le courriel.","aide":"Il se compose de haber au présent et d’un participe passé ; le marqueur « Hoy » l’appelle.","type":"zone","document":"correo","multiple":true},{"enonce":"Touche les **deux verbes à l’indefinido** : des actions achevées, coupées du présent.","aide":"Cherche les actions de la veille, introduites par le marqueur « Ayer ».","type":"zone","document":"correo","multiple":true},{"enonce":"Marta dit ce que faisait sa grand-mère chaque dimanche. Complète.","aide":"Une habitude du passé appelle l’imperfecto ; regarde aussi la personne du verbe.","type":"trous","segments":["Todos los domingos mi abuela ",0," paella."],"banque":["cocinaban","ha cocinado","cocinaba","cocinó"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m4"]},"explication":"**he escrito** : *haber* au présent + participe passé. Le perfecto relie l’action à aujourd’hui (« Hoy… »)."},{"cle":{"type":"zone","ids":["m11","m21"]},"explication":"**comí** et **vimos** sont à l’indefinido : *ayer* coupe l’action du présent, l’action est achevée."},{"cle":{"type":"trous","trous":[["cocinaba"]]},"affichage":"cocinaba","explication":"**cocinaba** : une habitude (« todos los domingos ») se met à l’imperfecto, ici à la 3e personne du singulier (-aba)."}]$ex$::jsonb),
  ('794c4be9-76d7-57d8-990b-ad3c6a37a92b'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Messages après une soirée sous la pluie","competence":"manier-langue","situation":"Lucas et Irene s’écrivent le lendemain d’une journée pluvieuse. À toi de choisir le bon passé dans chaque phrase.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages d’Irene et de Lucas","participants":[{"nom":"Irene","emoji":"👧","cote":"gauche"},{"nom":"Lucas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Irene","texte":"Lucas, ¿qué hiciste ayer?"},{"qui":"Lucas","texte":"Ayer fui a casa de Sara. Llovía mucho cuando salí de casa."},{"qui":"Irene","texte":"Yo me quedé en casa. Hoy he llegado tarde a clase."},{"qui":"Lucas","texte":"Mi abuelo siempre decía que la lluvia trae suerte."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes à l’imperfecto** : l’un plante un décor, l’autre dit une habitude.","aide":"Un verbe suit « siempre », l’autre dit ce qui durait quand Lucas est sorti.","type":"zone","document":"chat","multiple":true},{"enonce":"Touche le **marqueur de temps** qui appelle le *pretérito perfecto* (« he llegado »).","aide":"C’est un mot qui dit que le moment n’est pas encore fini.","type":"zone","document":"chat","multiple":false},{"enonce":"Associe chaque marqueur au temps qu’il appelle.","aide":"Pense à l’action achevée, au passé relié à aujourd’hui et à l’habitude.","type":"association","gauche":[{"id":"g0","texte":"ayer"},{"id":"g1","texte":"hoy"},{"id":"g2","texte":"siempre"}],"droite":[{"id":"d0","texte":"perfecto"},{"id":"d1","texte":"imperfecto"},{"id":"d2","texte":"indefinido"}]},{"enonce":"Complète avec la forme qui convient (nosotros, une action achevée la veille).","aide":"Ayer coupe du présent ; la personne est nosotros.","type":"trous","segments":["Ayer nosotros ",0," paella en casa de Sara."],"banque":["hemos comido","comemos","comieron","comimos"]},{"enonce":"Remets en ordre : « Il dormait quand le téléphone a sonné. » La phrase commence par Dormía.","aide":"L’imperfecto plante le décor, l’indefinido l’interrompt.","type":"ordre","items":[{"id":"a","texte":"el teléfono"},{"id":"b","texte":"Dormía"},{"id":"c","texte":"sonó"},{"id":"d","texte":"cuando"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m30"]},"explication":"**Llovía** (le décor) et **decía** (l’habitude : « siempre ») sont à l’imperfecto ; *fui*, *salí* et *me quedé* sont des actions achevées."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**Hoy** : la journée n’est pas finie, le passé reste relié au présent, donc *he llegado*."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"*Ayer* → **indefinido** (achevé), *hoy* → **perfecto** (relié au présent), *siempre* → **imperfecto** (habitude)."},{"cle":{"type":"trous","trous":[["comimos"]]},"affichage":"comimos","explication":"**comimos** : indefinido de *comer* à nosotros (-imos). *Hemos comido* serait fautif avec *ayer*."},{"cle":{"type":"ordre","ids":["b","d","c","a"]},"explication":"**Dormía cuando sonó el teléfono** : le décor à l’imperfecto, l’événement qui survient à l’indefinido."}]$ex$::jsonb),
  ('794c4be9-76d7-57d8-990b-ad3c6a37a92b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une nuit d’été à Séville","competence":"analyser-texte","situation":"Un récit de voyage mêle décor et événements. Une fiche de correction relève quatre phrases, dont une est fausse.","documents":[{"id":"noche","type":"texte","genre":"recit","titre":"Una noche en Sevilla","blocs":["Era una noche de verano en Sevilla. Hacía calor y la gente paseaba por la plaza.","De pronto, un músico empezó a cantar y todos se callaron. Cuando terminó, los turistas aplaudieron."],"source":"Texte écrit pour l’exercice"},{"id":"fichas","type":"tableau","titre":"Cuatro frases del cuaderno","colonnes":["Frase del alumno"],"lignes":[["Hoy he estudiado mucho."],["El año pasado viajé a Cuba."],["Ayer he comido paella."],["Esta semana he trabajado mucho."]],"enteteLignes":false,"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes qui plantent le décor** (imperfecto).","aide":"Ils disent ce qui durait : la nuit, la chaleur, les promenades.","type":"zone","document":"noche","multiple":true},{"enonce":"Touche les **quatre verbes qui font avancer l’action** (indefinido).","aide":"Ce sont des événements qui surviennent, chacun achevé.","type":"zone","document":"noche","multiple":true},{"enonce":"Dans le tableau, une phrase est **fautive**. Touche-la.","aide":"Regarde le marqueur de temps : est-il coupé du présent ou relié à lui ?","type":"zone","document":"fichas","multiple":false},{"enonce":"Pourquoi « Ayer he comido paella » est-elle fautive ?","aide":"Compare avec « Hoy he estudiado mucho » : qu’est-ce qui change ?","type":"choix","options":[{"id":"a","texte":"Avec ayer, l’espagnol exige toujours l’imparfait pour manger"},{"id":"b","texte":"Le perfecto est réservé aux verbes en -ar, pas en -er"},{"id":"c","texte":"Le mot paella impose le pretérito imperfecto dans ce cas"},{"id":"d","texte":"Ayer situe l’action hors du présent : il faut l’indefinido"}],"multiple":false},{"enonce":"Associe chaque verbe (personne et temps indiqués) à sa forme.","aide":"L’imparfait n’a que trois irréguliers : ser, ir, ver.","type":"association","gauche":[{"id":"g0","texte":"comer (él, indefinido)"},{"id":"g1","texte":"hablar (ellos, indefinido)"},{"id":"g2","texte":"vivir (nosotros, imparfait)"},{"id":"g3","texte":"ir (yo, imparfait)"}],"droite":[{"id":"d0","texte":"hablaron"},{"id":"d1","texte":"vivíamos"},{"id":"d2","texte":"iba"},{"id":"d3","texte":"comió"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m7","m12"]},"explication":"**Era, Hacía, paseaba** : l’imperfecto décrit le décor et ce qui durait."},{"cle":{"type":"zone","ids":["m20","m26","m28","m31"]},"explication":"**empezó, callaron, terminó, aplaudieron** : chaque événement rompt le décor, l’action avance."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**Ayer he comido paella** est fautive : *ayer* coupe du présent, il faut *Ayer comí paella*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Ayer coupe l’action du présent** : on emploie l’indefinido (*comí*). Le perfecto est réservé à ce qui touche encore à aujourd’hui."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"*comió* (-ió), *hablaron* (-aron), *vivíamos* (-íamos), *iba* (ir est un des trois irréguliers de l’imparfait)."}]$ex$::jsonb),
  ('8eafb2f8-b2cd-58a7-9796-3dd902c65eef'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Lucía se présente à Mateo","competence":"comprendre-langue","situation":"Lucía et Mateo se parlent pour la première fois par messages. Lucía est à Madrid et Mateo parle de sa mère.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Premiers messages","participants":[{"nom":"Lucía","emoji":"👧","cote":"gauche"},{"nom":"Mateo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lucía","texte":"Hola, soy Lucía y estoy en Madrid."},{"qui":"Mateo","texte":"¡Hola! Mi madre es profesora, pero hoy está cansada."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux formes du verbe estar** dans les messages.","aide":"Ce sont les verbes qui disent où Lucía se trouve et comment va la mère de Mateo.","type":"zone","document":"chat","multiple":true},{"enonce":"Pourquoi Lucía écrit-elle « estoy en Madrid » ?","aide":"Elle dit où elle se trouve en ce moment.","type":"choix","options":[{"id":"a","texte":"Madrid est l’heure : l’heure appelle estar"},{"id":"b","texte":"Madrid est où elle se trouve : localisation, donc estar"},{"id":"c","texte":"Madrid est sa profession : la profession appelle estar"},{"id":"d","texte":"Madrid est son origine : l’origine appelle estar"}],"multiple":false},{"enonce":"Mateo parle de sa mère. Complète avec le bon verbe.","aide":"Une profession dit ce que la personne est, pas comment elle va.","type":"trous","segments":["La madre de Mateo ",0," profesora."],"banque":["es","está","son","estoy"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m14"]},"explication":"**estoy** (localisation) et **está** (état passager) : *estar* dit où l’on se trouve et comment l’on va."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Localisation → estar** : *Madrid está en España*, *Lucía está en Madrid*. L’origine, elle, se dit avec *ser* (*soy de Valencia*)."},{"cle":{"type":"trous","trous":[["es"]]},"affichage":"es","explication":"**es** : une profession appelle *ser*. On dira *está cansada* pour l’état passager."}]$ex$::jsonb),
  ('8eafb2f8-b2cd-58a7-9796-3dd902c65eef'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La lettre d’Inés à sa correspondante","competence":"manier-langue","situation":"Inés écrit à Clara pour lui parler de sa famille. Attention : avec ser ou avec estar, un même adjectif change de sens.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Inés","blocs":["Querida Clara:","Mi hermano Álvaro es muy listo, pero hoy está malo: tiene fiebre y no está listo para ir al colegio.","En casa, la sopa de mi abuela está rica y el agua está fría.","Mi tío, en cambio, es rico: tiene tres coches y una casa enorme."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’adjectif qui veut dire « **malade** » (Álvaro a de la fièvre).","aide":"Il suit « está » et rime avec le contraire de « bueno ».","type":"zone","document":"carta","multiple":false},{"enonce":"Touche l’adjectif qui veut dire « **riche** » (de l’argent), et pas « délicieux ».","aide":"Deux mots se ressemblent dans la lettre : l’un parle de la soupe, l’autre de l’oncle.","type":"zone","document":"carta","multiple":false},{"enonce":"Que veut dire « no está listo para ir al colegio » ?","aide":"Compare « es muy listo » au début de la lettre et « no está listo ».","type":"choix","options":[{"id":"a","texte":"Il n’est pas prêt à aller au collège"},{"id":"b","texte":"Il n’est pas autorisé à aller au collège"},{"id":"c","texte":"Il n’est pas assez malin pour aller au collège"},{"id":"d","texte":"Il n’est pas content d’aller au collège"}],"multiple":false},{"enonce":"Complète pour dire qu’Álvaro s’ennuie en classe.","aide":"S’ennuyer est un état passager.","type":"trous","segments":["Mi hermano ",0," aburrido en clase."],"banque":["está","es","estoy","son"]},{"enonce":"Associe chaque expression à son sens.","aide":"Ser dit ce que la personne est ; estar dit comment elle va.","type":"association","gauche":[{"id":"g0","texte":"ser listo"},{"id":"g1","texte":"estar listo"},{"id":"g2","texte":"ser malo"},{"id":"g3","texte":"estar malo"}],"droite":[{"id":"d0","texte":"être prêt"},{"id":"d1","texte":"être méchant"},{"id":"d2","texte":"être malade"},{"id":"d3","texte":"être malin"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**está malo** : *estar malo* = être malade ; *ser malo* = être méchant."},{"cle":{"type":"zone","ids":["m41"]},"explication":"**es rico** : *ser rico* = être riche ; *estar rico* = être délicieux (la soupe *está rica*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**estar listo** = être prêt ; **ser listo** = être malin. Le verbe change le sens de l’adjectif."},{"cle":{"type":"trous","trous":[["esta"]]},"affichage":"está","explication":"**está aburrido** : *estar aburrido* = s’ennuyer ; *ser aburrido* = être ennuyeux."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Avec *ser*, c’est la nature (malin, méchant) ; avec *estar*, c’est un état (prêt, malade)."}]$ex$::jsonb),
  ('8eafb2f8-b2cd-58a7-9796-3dd902c65eef'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le groupe de messages du club de cinéma","competence":"manier-langue","situation":"Elena et Mario discutent dans le groupe du club d’espagnol, en 2026. Ils choisissent une séance au cinéma Alba.","documents":[{"id":"club","type":"dialogue","modele":"sms","titre":"Club de español","participants":[{"nom":"Elena","emoji":"👧","cote":"gauche"},{"nom":"Mario","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Elena","texte":"¡Hola, Mario! Hace tres años que estudio español."},{"qui":"Mario","texte":"Yo no. A mí me gusta mucho el cine español."},{"qui":"Elena","texte":"Y a mí me gustan las películas de Almodóvar. ¿Qué hay en el cine Alba?"},{"qui":"Mario","texte":"Mira la cartelera. Hoy estoy cansado, pero la sesión del sábado es muy buena."}],"source":"Messages écrits en 2026 pour l’exercice"},{"id":"cartelera","type":"fiche","modele":"affiche","entete":"Cine Alba","sousTitre":"Cartelera del sábado","emoji":"🎬","lignes":[{"texte":"Sala 1","valeur":"Comedia","id":"z1"},{"texte":"Sala 2","valeur":"Drama","id":"z2"},{"texte":"Sala 3","valeur":"Dibujos animados","id":"z3"}],"pied":"Hay entradas para todas las salas.","teinte":"violet"}],"questions":[{"enonce":"Touche la tournure qui exprime le **temps écoulé** depuis le début des études d’Elena.","aide":"C’est le mot qui ouvre la phrase d’Elena.","type":"zone","document":"club","multiple":false},{"enonce":"Les messages sont écrits en 2026. **En quelle année** Elena a-t-elle commencé l’espagnol ?","aide":"Hace tres años : retranche trois ans à 2026.","type":"nombre"},{"enonce":"Complète avec le verbe qui s’accorde avec ce qui plaît.","aide":"Gustar s’accorde avec la chose qui plaît, pas avec la personne.","type":"trous","segments":["A Elena le ",0," las películas de Almodóvar."],"banque":["gusto","gustas","gustan","gusta"]},{"enonce":"Mario veut voir un film d’animation. Touche la **salle** qui le projette.","aide":"Cherche l’expression qui veut dire « dessins animés ».","type":"zone","document":"cartelera","multiple":false},{"enonce":"Pourquoi Mario écrit-il « Hoy estoy cansado » et non « Hoy soy cansado » ?","aide":"Se demander si l’on décrit ce qu’est le sujet ou comment il va.","type":"choix","options":[{"id":"a","texte":"Être fatigué est une origine : on emploie estar"},{"id":"b","texte":"Être fatigué est un état passager : on emploie estar"},{"id":"c","texte":"Soy ne peut pas s’employer avec le mot hoy"},{"id":"d","texte":"Estar remplace ser avec tous les adjectifs en -ado"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"**Hace** : *hace tres años que estudio español* = j’étudie l’espagnol depuis trois ans."},{"cle":{"type":"nombre","valeur":2023,"tolerance":0},"affichage":"2023","explication":"2026 − 3 = **2023** : *hace tres años que* donne la durée écoulée."},{"cle":{"type":"trous","trous":[["gustan"]]},"affichage":"gustan","explication":"**gustan** : *las películas* est au pluriel, donc *gustan* (*me gustan las películas*)."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**Sala 3** : *dibujos animados* = dessins animés."},{"cle":{"type":"choix","ids":["b"]},"explication":"**estoy cansado** : l’état passager appelle *estar* ; *ser* décrirait ce que la personne est par nature."}]$ex$::jsonb),
  ('edd32eaf-5f53-54c3-bf0f-641af757fff8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’Espagne du XXe siècle sur une frise","competence":"se-reperer-temps","situation":"En préparant un exposé sur la mémoire, Hugo place sur une frise trois grandes périodes de l’histoire de l’Espagne.","documents":[{"id":"frise","type":"frise","titre":"Espagne, 1930-1980","debut":1930,"fin":1980,"pas":10,"periodes":[{"id":"z1","debut":1936,"fin":1939,"nom":"Guerre civile","teinte":"corail"},{"id":"z2","debut":1939,"fin":1975,"nom":"Franquisme","teinte":"ambre"},{"id":"z3","debut":1975,"fin":1978,"nom":"Transición","teinte":"turquoise"}],"evenements":[{"id":"z4","date":1978,"nom":"Constitution"}],"source":"Repères d’histoire de l’Espagne"}],"questions":[{"enonce":"Touche la période de la **dictature de Franco**.","aide":"C’est la plus longue des trois périodes.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’**années** a duré le franquisme ?","aide":"Retranche la date de début à la date de fin.","type":"nombre","unite":"ans"},{"enonce":"Touche l’**événement** qui marque la fin de la *transición*.","aide":"Il a lieu en 1978, quand l’Espagne se donne un nouveau texte fondateur.","type":"zone","document":"frise","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Le franquisme (1939-1975)** : c’est la longue dictature qui suit la guerre civile."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 ans","explication":"1975 − 1939 = **36 ans**."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**La Constitution de 1978** conclut la *transición* : l’Espagne passe de la dictature à la démocratie."}]$ex$::jsonb),
  ('edd32eaf-5f53-54c3-bf0f-641af757fff8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un Argentin et une Mexicaine discutent","competence":"comprendre-langue","situation":"Martín (Buenos Aires) et Ximena (Mexico) s’écrivent en espagnol. Leur façon de parler n’est pas la même, et aucune des deux n’est une faute.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages de Martín et de Ximena","participants":[{"nom":"Martín","emoji":"🧑","cote":"gauche"},{"nom":"Ximena","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Martín","texte":"Che, ¿vos tenés tiempo? Quiero mostrarte mi barrio de Buenos Aires."},{"qui":"Ximena","texte":"Sí. Voy a platicar contigo un rato, pero ahora manejo mi carro."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots du voseo** dans le message de Martín.","aide":"Il remplace *tú* et sa conjugaison est différente (*tienes* devient autre chose).","type":"zone","document":"chat","multiple":true},{"enonce":"Touche les **deux mots du lexique mexicain** dans le message de Ximena.","aide":"L’un remplace *hablar*, l’autre *coche*.","type":"zone","document":"chat","multiple":true},{"enonce":"En Espagne, on dit « coche ». Que penser du « carro » de Ximena ?","aide":"Une langue mondiale a plusieurs normes.","type":"choix","options":[{"id":"a","texte":"C’est un mot de l’espagnol ancien disparu"},{"id":"b","texte":"C’est une faute qu’un professeur doit corriger"},{"id":"c","texte":"C’est un mot qui n’existe qu’en Argentine"},{"id":"d","texte":"C’est une norme régionale, pas une faute"}],"multiple":false},{"enonce":"Associe chaque variante à l’endroit où on la rencontre.","aide":"Le seseo est une prononciation ; le voseo et le lexique mexicain se lisent dans les messages.","type":"association","gauche":[{"id":"g0","texte":"el voseo"},{"id":"g1","texte":"el seseo"},{"id":"g2","texte":"carro, platicar"}],"droite":[{"id":"d0","texte":"Andalousie et toute l’Amérique"},{"id":"d1","texte":"Mexique"},{"id":"d2","texte":"Argentine, Uruguay, Amérique centrale"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m2"]},"explication":"**vos tenés** : le *voseo* remplace *tú tienes* en Argentine, en Uruguay et en Amérique centrale."},{"cle":{"type":"zone","ids":["m14","m22"]},"explication":"**platicar** (parler) et **carro** (voiture) sont des mots mexicains courants."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Une norme régionale** : traiter ces variantes comme des écarts est un contresens sur ce qu’est une langue mondiale."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"*Voseo* : Argentine, Uruguay, Amérique centrale ; *seseo* : Andalousie et toute l’Amérique ; *carro, platicar* : Mexique."}]$ex$::jsonb),
