   $ex${"titre":"Des dictatures, un écrivain : la lettre de Valeria","competence":"analyser-document","situation":"Valeria prépare un exposé sur la mémoire. Elle a un tableau de repères et rédige un courriel pour son professeur.","documents":[{"id":"repere","type":"tableau","titre":"Repères de mémoire","colonnes":["Années","En Espagne","En Amérique latine"],"lignes":[["1936-1939","La guerra civil","—"],["1939-1975","El franquismo","—"],["1973-1990","—","Dictadura de Pinochet en Chile"],["1976-1983","—","Dictadura argentina"],["1975-1978","La transición, Constitución de 1978","—"]],"enteteLignes":true,"source":"Repères du cours"},{"id":"correo","type":"texte","genre":"lettre","titre":"Correo de Valeria","blocs":["Me llamo Valeria y estudio en Buenos Aires.","Mi vecina marcha con las Madres de Plaza de Mayo para recordar la dictadura. Mi amigo Tomás, que es chileno, me cuenta que en su país la dictadura terminó en 1990.","En clase de literatura leemos a García Márquez y hablamos del realismo mágico."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche la **case** du tableau qui parle de la dictature de Pinochet.","aide":"Cherche d’abord la ligne 1973-1990, puis la colonne de l’Amérique latine.","type":"zone","document":"repere","multiple":false},{"enonce":"Valeria vit à Buenos Aires. Combien d’**années** a duré la dictature argentine ?","aide":"Le tableau donne les dates ; la vecina des Madres de Plaza de Mayo est argentine.","type":"nombre","unite":"ans"},{"enonce":"La dictature chilienne a duré **combien d’années de plus** que la dictature argentine ?","aide":"Calcule les deux durées, puis fais la différence.","type":"nombre","unite":"ans"},{"enonce":"Touche le **nom de l’écrivain** associé au réalisme magique.","aide":"Son nom comprend deux mots, un prénom composé et un nom.","type":"zone","document":"correo","multiple":true},{"enonce":"Les Madres de Plaza de Mayo, citées par Valeria, sont liées à quelle période ?","aide":"Valeria habite à Buenos Aires.","type":"choix","options":[{"id":"a","texte":"La transition espagnole, 1975-1978"},{"id":"b","texte":"La dictature argentine, 1976-1983"},{"id":"c","texte":"La guerre civile espagnole, 1936-1939"},{"id":"d","texte":"La dictature chilienne, 1973-1990"}],"multiple":false}]}$ex$::jsonb,
