   $ex${"titre":"Une fiche du musée du Prado","competence":"analyser-texte","situation":"Léa visite le Prado. Elle lit la fiche qui accompagne un célèbre tableau de la salle de Velázquez.","documents":[{"id":"ficha","type":"texte","genre":"article","titre":"Ficha del museo","blocs":["*Las Meninas* es un cuadro de Diego Velázquez, pintado en 1656. En primer plano se ve a la infanta, rodeada de sus damas.","A la izquierda aparece el propio pintor, con el pincel en la mano: es un autorretrato dentro de un retrato de corte.","El cuadro está en el Museo del Prado, en Madrid."],"source":"Fiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui veut dire « **autoportrait** ».","aide":"Il commence par *auto-* et se termine comme *retrato*.","type":"zone","document":"ficha","multiple":false},{"enonce":"Que fait Velázquez dans ce tableau ?","aide":"Relis la deuxième phrase de la fiche.","type":"choix","options":[{"id":"a","texte":"Il n’apparaît pas : il ne peint que la cour"},{"id":"b","texte":"Il copie un autoportrait de Goya"},{"id":"c","texte":"Il peint le roi seul dans son palais"},{"id":"d","texte":"Il s’est peint lui-même, pinceau à la main"}],"multiple":false},{"enonce":"Touche le nom du **musée** où se trouve le tableau.","aide":"C’est le grand musée de Madrid, qui commence par P.","type":"zone","document":"ficha","multiple":false},{"enonce":"Complète la phrase pour décrire le premier plan.","aide":"Pour décrire un premier plan, on dit « En … plano se ve… ».","type":"trous","segments":["En ",0," plano se ve a la infanta."],"banque":["segundo","último","primer","gran"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m38"]},"explication":"**el autorretrato** = l’autoportrait : ici, Velázquez s’est représenté dans son propre tableau."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Il s’est représenté lui-même**, pinceau à la main : un autoportrait glissé dans un portrait de cour."},{"cle":{"type":"zone","ids":["m52"]},"explication":"**El Prado** : *Las Meninas* est au musée du Prado, à Madrid."},{"cle":{"type":"trous","trous":[["primer"]]},"affichage":"primer","explication":"**En primer plano se ve…** : c’est la formule pour décrire ce qui est au premier plan."}]$ex$::jsonb),
