   $ex${"titre":"Préparer l’oral sur Las dos Fridas","competence":"argumenter","situation":"Inés et Hugo préparent un oral sur l’autoportrait. Ils échangent des messages pour décrire le tableau, puis l’interpréter.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages d’Inés et d’Hugo","participants":[{"nom":"Inés","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inés","texte":"Para el oral voy a presentar *Las dos Fridas*. Es de 1939."},{"qui":"Hugo","texte":"Se ven dos Fridas sentadas. Una lleva un vestido europeo y la otra un traje mexicano."},{"qui":"Inés","texte":"Parece que la pintora quiere mostrar su doble identidad."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche l’**année** du tableau.","aide":"Inés la donne dans son premier message.","type":"zone","document":"chat","multiple":false},{"enonce":"Touche les **deux vêtements** que porte chaque Frida.","aide":"Hugo les oppose : l’un est européen, l’autre mexicain.","type":"zone","document":"chat","multiple":true},{"enonce":"Complète la phrase d’interprétation d’Inés.","aide":"Après quiere, on met un infinitif.","type":"trous","segments":["Parece que la pintora quiere ",0," su doble identidad."],"banque":["mostrado","mostrando","mostrar","muestra"]},{"enonce":"Remets en ordre : « Je crois que la peintre exprime son identité double. » La phrase commence par Creo.","aide":"Creo que + sujet + verbe + complément.","type":"ordre","items":[{"id":"a","texte":"Creo"},{"id":"b","texte":"la pintora"},{"id":"c","texte":"expresa"},{"id":"d","texte":"que"},{"id":"e","texte":"su doble identidad"}]},{"enonce":"Associe chaque œuvre ou description au peintre.","aide":"Trois peintres, trois autoportraits célèbres.","type":"association","gauche":[{"id":"g0","texte":"Las Meninas (1656)"},{"id":"g1","texte":"Las dos Fridas (1939)"},{"id":"g2","texte":"Il se peint vieilli et malade, sans flatterie"}],"droite":[{"id":"d0","texte":"Frida Kahlo"},{"id":"d1","texte":"Goya"},{"id":"d2","texte":"Velázquez"}]}]}$ex$::jsonb,
