   $ex${"titre":"Parler catalan, euskera ou guarani","competence":"analyser-document","situation":"Un article parle de trois adolescents espagnols et de leurs langues. Une carte permet de situer deux pays où des langues autres que le castillan sont officielles.","documents":[{"id":"mapaE","type":"carte","titre":"L’Europe du Sud-Ouest","fond":"europe","cadrage":[-12,34,8,46],"regionsCliquables":true,"source":"Fond de carte simplifié"},{"id":"mapaA","type":"carte","titre":"L’Amérique du Sud","fond":"monde","cadrage":[-85,-57,-30,14],"regionsCliquables":true,"source":"Fond de carte simplifié"},{"id":"articulo","type":"texte","genre":"article","titre":"Tres lenguas, tres identidades","blocs":["En Barcelona, Marta habla catalán en casa y castellano en el colegio. Su primo Iker, de Bilbao, habla euskera. Su amiga Brais, de Galicia, habla gallego.","La Constitución de 1978 reconoce estas lenguas en sus comunidades; el castellano es la lengua oficial del Estado.","En Paraguay, mucha gente habla guaraní y español: las dos lenguas son oficiales."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois langues** co-officielles dans leur communauté, à côté du castillan.","aide":"Ne touche pas le castillan, qui est la langue officielle de l’État.","type":"zone","document":"articulo","multiple":true},{"enonce":"En quelle **année** la Constitution espagnole reconnaît-elle ces langues ?","aide":"La date figure dans le deuxième paragraphe.","type":"nombre"},{"enonce":"Touche le **pays** où vivent Marta, Iker et Brais.","aide":"C’est dans la péninsule Ibérique, au nord-ouest du continent africain.","type":"zone","document":"mapaE","multiple":false},{"enonce":"Touche le **pays d’Amérique du Sud** où le guarani est langue co-officielle avec l’espagnol.","aide":"Il est enclavé, entre l’Argentine, la Bolivie et le Brésil.","type":"zone","document":"mapaA","multiple":false},{"enonce":"Associe chaque langue à son lieu.","aide":"Le spanglish mêle l’espagnol et l’anglais.","type":"association","gauche":[{"id":"g0","texte":"el guaraní"},{"id":"g1","texte":"el euskera"},{"id":"g2","texte":"el gallego"},{"id":"g3","texte":"el spanglish"}],"droite":[{"id":"d0","texte":"País Vasco"},{"id":"d1","texte":"Galicia"},{"id":"d2","texte":"Paraguay"},{"id":"d3","texte":"Estados Unidos"}]}]}$ex$::jsonb,
