   $ex${"titre":"Un autel pour les ancêtres","competence":"analyser-texte","situation":"Un article du journal du lycée présente le Día de Muertos au Mexique. Comment parler de cette fête sans la réduire à une seule lecture ?","documents":[{"id":"articulo","type":"texte","genre":"article","titre":"El Día de Muertos en México","blocs":["En México, el Día de Muertos se celebra el 1 y el 2 de noviembre. Las familias preparan ofrendas con fotos de los difuntos, flores de cempasúchil y calaveras de azúcar para recibir a sus antepasados.","Para unos es una tradición religiosa; para otros, una fiesta de la memoria. Es un patrimonio vivo que deja una huella en cada familia."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois éléments** qui composent l’offrande selon l’article.","aide":"Une image du défunt, une fleur, une friandise.","type":"zone","document":"articulo","multiple":true},{"enonce":"Touche les **deux mots** qui opposent deux points de vue (« Para… , para… »).","aide":"Ils suivent chacun « Para ».","type":"zone","document":"articulo","multiple":true},{"enonce":"Complète avec le bon mode après « Me parece importante que… ».","aide":"Après *Me parece importante que*, on emploie le subjonctif.","type":"trous","segments":["Me parece importante que las familias ",0," a sus antepasados."],"banque":["recuerden","recuerdan","recordar","recordarán"]},{"enonce":"Associe chaque mot du texte à sa traduction.","aide":"Ces quatre mots figurent dans l’article.","type":"association","gauche":[{"id":"g0","texte":"la huella"},{"id":"g1","texte":"el patrimonio"},{"id":"g2","texte":"el antepasado"},{"id":"g3","texte":"la ofrenda"}],"droite":[{"id":"d0","texte":"le patrimoine"},{"id":"d1","texte":"l’ancêtre"},{"id":"d2","texte":"l’autel d’offrandes"},{"id":"d3","texte":"la trace"}]}]}$ex$::jsonb,
