   $ex${"titre":"Un même 12 octobre, trois récits","competence":"analyser-document","situation":"Camilo prépare un exposé sur le 12 octobre. Il croise un article et une carte pour comprendre pourquoi la même date porte trois noms.","documents":[{"id":"mapaE","type":"carte","titre":"L’Europe du Sud-Ouest","fond":"europe","cadrage":[-12,34,8,46],"regionsCliquables":true,"source":"Fond de carte simplifié"},{"id":"mapaA","type":"carte","titre":"L’Amérique du Sud","fond":"monde","cadrage":[-85,-57,-30,14],"regionsCliquables":true,"source":"Fond de carte simplifié"},{"id":"articulo","type":"texte","genre":"article","titre":"Una fecha, tres nombres","blocs":["El 12 de octubre de 1492, Cristóbal Colón llegó a América. Hoy esa fecha tiene tres nombres.","En España es la Fiesta Nacional. En Venezuela, desde 2002, se llama Día de la Resistencia Indígena. En Argentina, desde 2010, es el Día del Respeto a la Diversidad Cultural."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pays où le 12 octobre est la **Fiesta Nacional**.","aide":"C’est le pays dont Colomb est parti pour son voyage de 1492.","type":"zone","document":"mapaE","multiple":false},{"enonce":"Touche les **deux pays d’Amérique du Sud** où cette date a été rebaptisée.","aide":"L’article en cite deux après l’Espagne : l’un depuis 2002, l’autre depuis 2010.","type":"zone","document":"mapaA","multiple":true},{"enonce":"Combien d’**années** séparent le changement de nom vénézuélien de l’argentin ?","aide":"Relève les deux années dans l’article.","type":"nombre","unite":"ans"},{"enonce":"Remets en ordre : « Pour les uns c’est une fête, pour les autres une polémique. » La phrase commence par Para unos.","aide":"La tournure oppose deux points de vue.","type":"ordre","items":[{"id":"a","texte":"para otros"},{"id":"b","texte":"es una fiesta"},{"id":"c","texte":"una polémica"},{"id":"d","texte":"Para unos"}]},{"enonce":"Que montre le fait qu’une même date porte trois noms ?","aide":"Même date, trois récits.","type":"choix","options":[{"id":"a","texte":"Que la date est fériée dans le monde entier"},{"id":"b","texte":"Que Colomb n’est pas arrivé en 1492"},{"id":"c","texte":"Que les trois pays ont la même histoire"},{"id":"d","texte":"Que le récit national fait débat selon les pays"}],"multiple":false}]}$ex$::jsonb,
