   $ex${"titre":"La mode, miroir de la société","competence":"analyser-texte","situation":"Un article du journal du lycée compare trois noms de la mode espagnole et latino-américaine, de Balenciaga à Zara.","documents":[{"id":"moda","type":"texte","genre":"article","titre":"La moda y la sociedad","blocs":["Cristóbal Balenciaga nació en Getaria, en el País Vasco, en 1895. Fue un gran diseñador y se inspiró en los trajes españoles.","La empresa Zara nació en Galicia en 1975 y hoy es un símbolo de la moda rápida.","En 2019, México criticó a la diseñadora venezolana Carolina Herrera: usó motivos indígenas sin citarlos. Es el debate sobre la apropiación cultural."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le nom de la **région** où est née l’entreprise Zara.","aide":"C’est une communauté du nord-ouest de l’Espagne.","type":"zone","document":"moda","multiple":false},{"enonce":"Combien d’**années** séparent la naissance de Balenciaga de la fondation de Zara ?","aide":"Relève les deux années dans l’article.","type":"nombre","unite":"ans"},{"enonce":"Que reproche le Mexique à Carolina Herrera en 2019 ?","aide":"Relis la dernière partie de l’article.","type":"choix","options":[{"id":"a","texte":"D’avoir vendu ses vêtements à des prix trop bas"},{"id":"b","texte":"D’avoir copié les robes de Balenciaga"},{"id":"c","texte":"D’avoir repris des motifs indigènes sans les citer"},{"id":"d","texte":"D’avoir quitté le Venezuela pour l’Espagne"}],"multiple":false},{"enonce":"Complète pour dire que le créateur puise son inspiration dans les costumes traditionnels.","aide":"Le sujet est un seul créateur ; le verbe est au présent.","type":"trous","segments":["El diseñador se ",0," en los trajes tradicionales."],"banque":["inspiran","inspira","inspirar","inspirado"]},{"enonce":"Associe chaque mot à sa traduction.","aide":"Certains de ces mots figurent dans l’article.","type":"association","gauche":[{"id":"g0","texte":"la obra maestra"},{"id":"g1","texte":"e