   $ex${"titre":"Trois légendes qui voyagent","competence":"analyser-document","situation":"Pour une exposition sur les légendes, un article présente La Llorona, El Dorado et Don Quichotte. Une carte permet de situer les deux légendes américaines.","documents":[{"id":"mapa","type":"carte","titre":"Le Mexique et la Colombie","fond":"monde","cadrage":[-120,-8,-65,33],"regionsCliquables":true,"source":"Fond de carte simplifié"},{"id":"leyendas","type":"texte","genre":"article","titre":"Tres leyendas","blocs":["La Llorona es una mujer que llora por la noche y busca a sus hijos. Es una leyenda de México.","El Dorado nace de un rito de los muiscas en la laguna de Guatavita, en Colombia. Esta leyenda lanzó a los conquistadores en busca de una ciudad imaginaria.","Don Quijote, de Cervantes (1605 y 1615), es un caballero que confunde molinos con gigantes."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pays d’où vient la légende de **La Llorona**.","aide":"L’article le précise à la fin du premier paragraphe.","type":"zone","document":"mapa","multiple":false},{"enonce":"Touche le pays où se trouve la **lagune de Guatavita**, source du mythe d’El Dorado.","aide":"C’est un pays du nord-ouest de l’Amérique du Sud.","type":"zone","document":"mapa","multiple":false},{"enonce":"Touche le nom du **peuple** à l’origine du mythe d’El Dorado.","aide":"Il célébrait un rite à la lagune.","type":"zone","document":"leyendas","multiple":false},{"enonce":"Combien d’**années** séparent les deux parties de *Don Quijote* ?","aide":"Relève les deux dates entre parenthèses.","type":"nombre","unite":"ans"},{"enonce":"Remets en ordre : « Ce film rend hommage à la légende de La Llorona. » La phrase commence par Esta película.","aide":"*Rendre hommage* se dit *rendir homenaje*.","type":"ordre","items":[{"id":"a","texte":"rinde homenaje"},{"id":"b","texte":"Esta película"},{"id":"c","texte":"a la leyenda"},{"id":"d","texte":"de La Llorona"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["MEX"]},"explication":"**Le Mexique** : La Llorona est une femme en pleurs qui cherche ses enfants la nuit."},{"cle":{"type":"zone","ids":["COL"]},"explication":"**La Colombie** : le mythe d’El Dorado naît d’un rite muisca à la lagune de Guatavita."},{"cle":{"type":"zone","ids":["m28"]},"explication":"**Les muiscas** : un rite muisca à la lagune de Guatavita est à l’origine du mythe du roi couvert d’or."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 ans","explication":"1615 − 1605 = **10 ans**."},{"cle":{"type":"ordre","ids":["b","a","c","d"]},"explication":"**Esta película rinde homenaje a la leyenda de La Llorona** : *rendir homenaje a* = rendre hommage à."}]$ex$::jsonb),
