   $ex${"titre":"Une affiche de 1964 : quelle Espagne ?","competence":"analyser-document","situation":"Au grenier, Marta trouve une affiche touristique qui ressemble à celles des années 1960. Elle se demande si elle montre toute l’Espagne ou seulement quelques images.","documents":[{"id":"cartel","type":"fiche","modele":"affiche","entete":"¡Visite España!","sousTitre":"Cartel turístico","emoji":"☀️","lignes":[{"texte":"Sol y playa todo el año","id":"z1"},{"texte":"Flamenco y toros en cada pueblo","id":"z2"},{"texte":"Paella para todos","id":"z3"}],"pied":"¡Venga a conocer el país de la fiesta!","teinte":"ambre","source":"Affiche imaginée pour l’exercice, dans le style des années 1960"}],"questions":[{"enonce":"Touche la ligne de l’affiche qui annonce un **plat**.","aide":"Cherche le plat de riz, spécialité de Valence.","type":"zone","document":"cartel","multiple":false},{"enonce":"Que montre surtout cette affiche ?","aide":"Soleil, flamenco, toros, paella : combien d’images différentes ? Est-ce tout le pays ?","type":"choix","options":[{"id":"a","texte":"Le programme d’une visite guidée de Madrid"},{"id":"b","texte":"Les paysages différents des 17 communautés"},{"id":"c","texte":"Des clichés : l’Espagne réduite à quelques images"},{"id":"d","texte":"Un plan de la côte de Galice"}],"multiple":false},{"enonce":"Complète la formule qui sert à contredire un cliché.","aide":"Après *se suele*, on met un infinitif.","type":"trous","segments":["Se suele ",0," que en España hay sol todo el año."],"banque":["piensa","pensar","pensando","pienso"]}]}$ex$::jsonb,
