   $ex${"titre":"Visiter Madrid avec une amie madrilène","competence":"se-reperer-temps","situation":"Tom arrive à Madrid. Lucía, sa correspondante, lui explique le programme et lui rappelle quelques dates de la ville.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages de Lucía et de Tom","participants":[{"nom":"Lucía","emoji":"👩","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lucía","texte":"¡Bienvenido a Madrid, Tom! Mañana empezamos en la Puerta del Sol, el kilómetro cero de las carreteras de España."},{"qui":"Tom","texte":"¿Y es verdad que se comen doce uvas allí?"},{"qui":"Lucía","texte":"Sí, a medianoche, el 31 de diciembre. Por la tarde vamos al Reina Sofía, donde está el *Guernica* de Picasso."},{"qui":"Tom","texte":"¿Y el Retiro?"},{"qui":"Lucía","texte":"El domingo. El Paseo del Prado y el Retiro son patrimonio de la UNESCO desde 2021."}],"source":"Messages écrits pour l’exercice"},{"id":"frise","type":"frise","titre":"Madrid, de 1550 à 2050","debut":1550,"fin":2050,"pas":50,"periodes":[{"id":"z1","debut":1980,"fin":1989,"nom":"La Movida","teinte":"rose"}],"evenements":[{"id":"z2","date":1561,"nom":"Madrid, capital"},{"id":"z3","date":1937,"nom":"Guernica"},{"id":"z4","date":2021,"nom":"Paisaje de la Luz"}],"source":"Repères d’histoire de Madrid"}],"questions":[{"enonce":"Touche ce que l’on mange à minuit, le 31 décembre, à la Puerta del Sol.","aide":"Il y en a douze, un par coup de minuit : ce sont des fruits.","type":"zone","document":"chat","multiple":false},{"enonce":"Touche l’événement qui fait de Madrid la **capitale** : Philippe II y installe la cour.","aide":"C’est le plus ancien des trois événements de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’installation de la capitale (1561) de l’inscription du Paseo del Prado et du Retiro à l’UNESCO (2021) ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre"},{"enonce":"Associe chaque lieu ou repère à ce qu’il faut en retenir.","aide":"Relis les messages de Lucía et regarde la frise.","type":"association","gauche":[{"id":"g0","texte":"La Puerta del Sol"},{"id":"g1","texte":"Le musée Reina Sofía"},{"id":"g2","texte":"La Movida"},{"id":"g3","texte":"Le Paseo del Prado et le Retiro"}],"droite":[{"id":"d0","texte":"Le « Paysage de la lumière » (UNESCO)"},{"id":"d1","texte":"Le *Guernica* de Picasso"},{"id":"d2","texte":"Une explosion culturelle des années 1980"},{"id":"d3","texte":"Le kilomètre zéro des routes d’Espagne"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m26"]},"explication":"**Las uvas** : on mange douze raisins à minuit, un à chaque coup de cloche, le 31 décembre."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**1561** : Philippe II installe la cour à Madrid, qui devient la capitale."},{"cle":{"type":"nombre","valeur":460,"tolerance":0},"affichage":"460","explication":"2021 − 1561 = **460 ans**."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"La Puerta del Sol est le **kilomètre zéro**, le Reina Sofía garde *Guernica*, la **Movida** date des années 1980 et le Prado-Retiro forme le **Paysage de la lumière**."}]$ex$::jsonb),
  ('0f1e0d1e-c934-50c7-a7c7-fe95c62ab731'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La mer en danger : Galice et Murcie","competence":"lire-carte","situation":"Pour un exposé, Hugo compare deux atteintes à la mer espagnole. Il a un article et une carte muette pour situer les deux cas.","documents":[{"id":"carte","type":"carte","titre":"L’Espagne et ses côtes","fond":"europe","cadrage":[-12,35,5,45],"lieux":[{"id":"z1","lon":-9,"lat":43.1,"symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lon":-0.8,"lat":37.7,"symbole":"lettre","lettre":"B","teinte":"violet"},{"id":"z3","lieu":"madrid","symbole":"lettre","lettre":"C","teinte":"ambre"}],"source":"Fond de carte simplifié"},{"id":"art","type":"texte","genre":"article","titre":"Dos golpes al mar","blocs":["El *Prestige* era un petrolero. En 2002 se hundió frente a las costas de Galicia y la marea negra llegó a las playas. Miles de voluntarios las limpiaron y nació el movimiento *Nunca Máis*.","La Mar Menor, en Murcia, es una laguna contaminada por la agricultura intensiva. En 2022, una ley le dio personalidad jurídica: fue una primera en Europa."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le repère qui correspond à la **Galice**, touchée par la marée noire du *Prestige*.","aide":"La Galice est tout au nord-ouest de la péninsule.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le repère qui correspond à la **Mar Menor**, la lagune de Murcie.","aide":"Murcie est sur la côte méditerranéenne, au sud-est.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les deux mots qui désignent le **statut juridique** donné à la Mar Menor en 2022.","aide":"C’est un nom suivi d’un adjectif : la lagune devient comme une « personne » devant la loi.","type":"zone","document":"art","multiple":true},{"enonce":"Combien d’années séparent le naufrage du *Prestige* de la loi sur la Mar Menor ?","aide":"Relève les deux années dans l’article.","type":"nombre"},{"enonce":"Quelle est la nature de chaque cas, dans l’ordre de l’article (le *Prestige*, puis la Mar Menor) ?","aide":"Cherche l’origine de chaque pollution dans l’article.","type":"choix","options":[{"id":"a","texte":"Une pollution par les engrais, puis un accident de pétrolier"},{"id":"b","texte":"Un accident de pétrolier, puis une pollution agricole lente"},{"id":"c","texte":"Une marée noire en Méditerranée, puis une pollution en Atlantique"},{"id":"d","texte":"Deux naufrages de pétroliers survenus à vingt ans d’écart"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**A** : la Galice occupe le nord-ouest de l’Espagne, face à l’Atlantique."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**B** : la Mar Menor est une lagune de la région de Murcie, au sud-est de l’Espagne."},{"cle":{"type":"zone","ids":["m53","m54"]},"explication":"**personalidad jurídica** : en 2022, la Mar Menor a reçu la personnalité juridique, une première en Europe."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20","explication":"2022 − 2002 = **20 ans**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le *Prestige* est un **accident** (marée noire), la Mar Menor est polluée **lentement** par l’agriculture intensive : deux causes, deux façons de protéger la mer."}]$ex$::jsonb),
  ('a2c23e67-374d-5cae-9fd8-f6d6d329779d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le règlement de la salle de classe","competence":"comprendre-langue","situation":"Dans son nouveau lycée, Noa lit le règlement affiché près de la porte de la salle d’espagnol.","documents":[{"id":"normas","type":"fiche","modele":"panneau","entete":"Normas de la clase","emoji":"📚","lignes":[{"texte":"Entra en silencio.","id":"z1"},{"texte":"Apaga el móvil.","id":"z2"},{"texte":"No corras por el pasillo.","id":"z3"},{"texte":"No comas en clase.","id":"z4"}],"teinte":"violet","source":"Panneau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux **défenses** (ordres négatifs) du règlement.","aide":"Cherche le petit mot *no* au début de la phrase.","type":"zone","document":"normas","multiple":true},{"enonce":"À quel temps est le verbe de « No comas en clase » ?","aide":"Rappelle-toi la formule : l’impératif négatif = *no* + …","type":"choix","options":[{"id":"a","texte":"Au futur de l’indicatif"},{"id":"b","texte":"À l’indicatif présent"},{"id":"c","texte":"À l’impératif affirmatif"},{"id":"d","texte":"Au subjonctif présent"}],"multiple":false},{"enonce":"Complète la nouvelle règle : « N’utilise pas le portable en classe. »","aide":"Défense à *tú* : *no* + subjonctif présent. Pense à *comer → comas*.","type":"trous","segments":["No ",0," el móvil en clase."],"banque":["usa","usar","usas","uses"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3","z4"]},"explication":"**No corras** et **no comas** : à l’impératif négatif, on met *no* devant le verbe."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Subjonctif présent** : l’impératif négatif se forme avec *no* + subjonctif présent (*comas*, *corras*)."},{"cle":{"type":"trous","trous":[["uses"]]},"affichage":"uses","explication":"**No uses** : verbe *usar*, subjonctif présent, personne *tú*."}]$ex$::jsonb),
  ('a2c23e67-374d-5cae-9fd8-f6d6d329779d'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Les ordres de maman avant le dîner","competence":"manier-langue","situation":"Lucas rentre à la maison. Sa mère lui écrit une série de consignes, et lui répond avec quelques demandes.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages de Mamá et de Lucas","participants":[{"nom":"Mamá","emoji":"👩","cote":"gauche"},{"nom":"Lucas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mamá","texte":"Lucas, haz los deberes y sal con el perro, por favor."},{"qui":"Lucas","texte":"Vale. ¿Y la cena?"},{"qui":"Mamá","texte":"Ten paciencia. Ven a la cocina a las nueve y come la sopa."},{"qui":"Lucas","texte":"¿Puedo ver la tele? Di que sí, mamá."},{"qui":"Mamá","texte":"Ahora no. Lávate las manos y no llegues tarde a la mesa."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche toutes les formes d’impératif **tú irrégulières** (celles des « huit irréguliers »).","aide":"Il y en a cinq : celles de *hacer*, *salir*, *tener*, *venir* et *decir*.","type":"zone","document":"chat","multiple":true},{"enonce":"Quel est l’infinitif de la forme « **ten** » dans « Ten paciencia » ?","aide":"Dans la liste des irréguliers, pense à *tener → ten*.","type":"choix","options":[{"id":"a","texte":"tenar"},{"id":"b","texte":"tenir"},{"id":"c","texte":"tener"},{"id":"d","texte":"tenor"}],"multiple":false},{"enonce":"Complète la défense de la mère.","aide":"Au négatif, on passe au subjonctif présent.","type":"trous","segments":["No ",0," tarde a la mesa."],"banque":["llegar","llega","llegas","llegues"]},{"enonce":"Remets en ordre : « Ne te lève pas de la table. » La phrase commence par *No*.","aide":"Au négatif, le pronom se place **devant** le verbe.","type":"ordre","items":[{"id":"a","texte":"No"},{"id":"b","texte":"levantes"},{"id":"c","texte":"de la mesa"},{"id":"d","texte":"te"}]},{"enonce":"Associe chaque ordre affirmatif à sa défense (tú).","aide":"Le négatif vient de la forme *yo* du subjonctif : *hago → hagas*.","type":"association","gauche":[{"id":"g0","texte":"haz"},{"id":"g1","texte":"di"},{"id":"g2","texte":"sal"},{"id":"g3","texte":"ve"}],"droite":[{"id":"d0","texte":"no vayas"},{"id":"d1","texte":"no digas"},{"id":"d2","texte":"no hagas"},{"id":"d3","texte":"no salgas"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m5","m15","m17","m32"]},"explication":"**haz, sal, ten, ven, di** : ce sont cinq des huit irréguliers à la personne *tú*. *Come* et *lávate* sont réguliers."},{"cle":{"type":"choix","ids":["c"]},"explication":"**tener** : l’impératif tú est *ten*, comme *venir → ven*."},{"cle":{"type":"trous","trous":[["llegues"]]},"affichage":"llegues","explication":"**No llegues** : *no* + subjonctif présent de *llegar*."},{"cle":{"type":"ordre","ids":["a","d","b","c"]},"explication":"**No te levantes de la mesa** : à l’impératif négatif, les pronoms se placent devant le verbe."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"**haz → no hagas**, **di → no digas**, **sal → no salgas**, **ve → no vayas** : le négatif passe toujours par le subjonctif."}]$ex$::jsonb),
  ('a2c23e67-374d-5cae-9fd8-f6d6d329779d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Au camp d’été : pronoms et impératifs","competence":"manier-langue","situation":"Au camp d’été, Marta, la monitrice, donne ses consignes à Dani et aux autres jeunes. Un tableau résume les formes les plus piégeuses.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages de Marta et de Dani","participants":[{"nom":"Marta","emoji":"👩","cote":"gauche"},{"nom":"Dani","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marta","texte":"¡Buenos días! Levantaos, que son las siete."},{"qui":"Dani","texte":"¿Qué hacemos primero?"},{"qui":"Marta","texte":"Lavaos los dientes y sentaos a desayunar. Y las mochilas: no las olvidéis."}],"source":"Messages écrits pour l’exercice"},{"id":"tab","type":"tableau","titre":"Des ordres avec pronoms","colonnes":["Verbe","Affirmatif","Négatif"],"lignes":[["decir + me + lo (tú)","?","no me lo digas"],["levantarse (tú)","levántate","no te levantes"],["sentarse (nosotros)","sentémonos","no nos sentemos"],["lavarse (vosotros)","lavaos","no os lavéis"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’impératif **vosotros** du verbe *levantarse* dans les messages.","aide":"Il se termine par *-aos* : le *-d* de l’infinitif en *-ad* tombe devant *os*.","type":"zone","document":"chat","multiple":false},{"enonce":"Complète la case « ? » : « Dis-le-moi » (tú), en un mot.","aide":"Impératif tú de *decir*, puis *me* + *lo* soudés à la fin, avec un accent écrit.","type":"texte","placeholder":"dímelo"},{"enonce":"Complète en t’aidant du tableau : « Ne vous asseyez pas par terre, les enfants ! »","aide":"Compare avec *no os lavéis* : le négatif passe au subjonctif, pronom devant.","type":"trous","segments":["No os ",0," en el suelo, chicos."],"banque":["sentados","sentaos","sentad","sentéis"]},{"enonce":"Touche l’impératif **négatif** adressé à plusieurs jeunes (*vosotros*).","aide":"Marta emploie *no las* devant le verbe, avec un -éis.","type":"zone","document":"chat","multiple":false},{"enonce":"Marta parle maintenant à la directrice du camp (*usted*). Comment lui dit-elle « Levez-vous » ?","aide":"Pour *usted*, l’impératif emprunte le subjonctif présent ; le pronom se soude à la fin.","type":"choix","options":[{"id":"a","texte":"Levántate"},{"id":"b","texte":"Levantaos"},{"id":"c","texte":"Levántense"},{"id":"d","texte":"Levántese"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"**Levantaos** : *levantad* + *os* → le -d tombe devant *os*."},{"cle":{"type":"texte","acceptes":["dimelo"]},"affichage":"dímelo","explication":"**dímelo** : *di* + *me* + *lo* ; l’accent écrit garde l’accent tonique sur le *í*."},{"cle":{"type":"trous","trous":[["senteis"]]},"affichage":"sentéis","explication":"**No os sentéis** : *no* + *os* + subjonctif présent *(vosotros)*."},{"cle":{"type":"zone","ids":["m22"]},"explication":"**olvidéis** : *no las olvidéis* = *no* + pronom + subjonctif *(vosotros)*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Levántese** : subjonctif *levante* + pronom *se* soudé, avec accent écrit."}]$ex$::jsonb),
  ('2aee1ab0-684b-522d-9089-53ec4ebdf184'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une sortie à Tolède : lire l’affiche","competence":"comprendre-langue","situation":"Le lycée organise une excursion à Tolède. Inès lit l’affiche du hall pour savoir quoi faire.","documents":[{"id":"cartel","type":"fiche","modele":"affiche","entete":"Excursión a Toledo","sousTitre":"Cartel del instituto","emoji":"🚌","lignes":[{"texte":"Salida","valeur":"a las 8, por la mañana","id":"z1"},{"texte":"Autobús","valeur":"para Toledo","id":"z2"},{"texte":"Inscripción","valeur":"para el viernes","id":"z3"},{"texte":"Precio","valeur":"quince euros","id":"z4"}],"teinte":"violet","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui donne la **date limite** pour s’inscrire.","aide":"La date limite se dit avec *para* (« pour vendredi »).","type":"zone","document":"cartel","multiple":false},{"enonce":"Dans « a las 8, **por** la mañana », que marque *por* ?","aide":"On dit aussi *por la tarde*, *por la noche*.","type":"choix","options":[{"id":"a","texte":"La cause du départ"},{"id":"b","texte":"Le moment de la journée"},{"id":"c","texte":"La destination du bus"},{"id":"d","texte":"Le but de l’excursion"}],"multiple":false},{"enonce":"Complète les deux phrases.","aide":"Premier trou : une destination ; second trou : on remercie « à cause de ».","type":"trous","segments":["El autobús sale ",0," Toledo. Gracias ",1," venir."],"banque":["por","a","de","para"]}]}$ex$::jsonb,
