  ('2aee1ab0-684b-522d-9089-53ec4ebdf184'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un cadeau d’anniversaire entre amis","competence":"manier-langue","situation":"Sofía fête son anniversaire. Álex lui offre un cadeau, puis ils se parlent par messages.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages de Sofía et d’Álex","participants":[{"nom":"Sofía","emoji":"👧","cote":"gauche"},{"nom":"Álex","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Sofía","texte":"Gracias por venir a mi cumpleaños, Álex."},{"qui":"Álex","texte":"Esto es para ti. Lo compré por veinte euros."},{"qui":"Sofía","texte":"¡Qué bonito! Mañana te llamo por teléfono para darte las gracias otra vez."},{"qui":"Álex","texte":"Gracias a ti. Ahora tengo que estudiar para el lunes, pero por la tarde estoy libre."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Complète le message de Sofía.","aide":"Premier trou : le moyen de communication ; second trou : le but, devant un infinitif.","type":"trous","segments":["Te llamo ",0," teléfono ",1," darte las gracias."],"banque":["para","por","en","a"]},{"enonce":"Range ces morceaux de phrases selon la préposition qui manque.","aide":"Pose-toi la question : « dans quel but ? » (para) ou « à cause de quoi, pour quel prix ? » (por).","type":"categories","categories":[{"id":"c0","texte":"por"},{"id":"c1","texte":"para"}],"items":[{"id":"i0","texte":"Gracias ___ venir"},{"id":"i1","texte":"___ mí, es un regalo muy bonito"},{"id":"i2","texte":"Estudiar ___ el lunes"},{"id":"i3","texte":"Lo compré ___ veinte euros"},{"id":"i4","texte":"Esto es ___ ti"}]},{"enonce":"Touche le jour pour lequel Álex doit **étudier**.","aide":"C’est un jour de la semaine, après *para el*.","type":"zone","document":"chat","multiple":false},{"enonce":"Dans « **por** la tarde estoy libre », *por* exprime…","aide":"Compare avec *por la mañana*.","type":"choix","options":[{"id":"a","texte":"Un point de vue personnel"},{"id":"b","texte":"Un prix payé en euros"},{"id":"c","texte":"Une destination précise"},{"id":"d","texte":"Un moment de la journée"}],"multiple":false}]}$ex$::jsonb,
