  ('2aee1ab0-684b-522d-9089-53ec4ebdf184'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Marcos part pour Séville, via Cordoue","competence":"lire-carte","situation":"Marcos écrit à Clara pour annoncer son voyage. Sur une carte, tu repères sa destination et sa ville de passage.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Marcos","blocs":["Querida Clara:","Gracias por tu mensaje. Esta semana trabajo por mi hermano, que está enfermo.","El viernes salgo de Madrid para Sevilla y paso por Córdoba para ver a mis primos. ¡Por fin voy a conocer tu ciudad!","Te llamo por teléfono para contarte el viaje. Un abrazo, Marcos"],"source":"Lettre écrite pour l’exercice"},{"id":"mapa","type":"carte","titre":"Madrid et l’Andalousie","fond":"europe","cadrage":[-10,35.5,0,44],"lieux":[{"id":"z1","lieu":"madrid","nom":"Madrid","symbole":"point"},{"id":"z2","lon":-4.78,"lat":37.89,"nom":"Córdoba","symbole":"point"},{"id":"z3","lieu":"seville","nom":"Sevilla","symbole":"point"}],"source":"Fond de carte simplifié"}],"questions":[{"enonce":"Touche la ville **vers laquelle** Marcos part (destination).","aide":"Relis : *salgo de Madrid para…*","type":"zone","document":"mapa","multiple":false},{"enonce":"Touche la ville que Marcos **traverse** en chemin.","aide":"Relis : *paso por…*","type":"zone","document":"mapa","multiple":false},{"enonce":"Touche le mot qui dit pour **qui** Marcos travaille à sa place.","aide":"C’est un membre de la famille, malade cette semaine.","type":"zone","document":"carta","multiple":false},{"enonce":"Que signifie « trabajo **por** mi hermano » ?","aide":"*Por* peut vouloir dire « à la place de » ou « en faveur de ».","type":"choix","options":[{"id":"a","texte":"Je travaille près de chez mon frère"},{"id":"b","texte":"Je travaille pour mon frère, qui est mon patron"},{"id":"c","texte":"Je travaille à la place de mon frère"},{"id":"d","texte":"Je travaille afin d’aller voir mon frère"}],"multiple":false},{"enonce":"Complète deux phrases inspirées de la lettre.","aide":"Premier trou : à la place de quelqu’un ; second trou : destination.","type":"trous","segments":["Esta semana trabajo ",0," mi hermano. El viernes salgo ",1," Sevilla."],"banque":["de","para","por","a"]}]}$ex$::jsonb,
