  ('5c2c1c34-c99f-5efd-9de8-e36dee8a407a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre pour un week-end à Tolède","competence":"manier-langue","situation":"Irene écrit à Teo pour l’inviter à Tolède. Tu observes où elle met un a devant une personne, et où elle n’en met pas.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Irene","blocs":["Hola, Teo:","El sábado voy a Toledo a ver a mis abuelos. Llego a las diez, en tren.","Quiero mucho a mis abuelos y también a su perro, Toby. Tengo dos primos allí, pero no conozco a nadie más.","Busco un compañero de viaje: ¿vienes?"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Dans la lettre d’Irene, range ces phrases selon qu’il y a un *a* devant le complément ou non.","aide":"Personne précise, animal familier ou *nadie* : *a*. Après *tener*, ou pour une personne quelconque : rien.","type":"categories","categories":[{"id":"c0","texte":"On met a"},{"id":"c1","texte":"Pas de a"}],"items":[{"id":"i0","texte":"Tengo ___ dos primos allí"},{"id":"i1","texte":"Quiero también ___ su perro"},{"id":"i2","texte":"Quiero mucho ___ mis abuelos"},{"id":"i3","texte":"Busco ___ un compañero de viaje"},{"id":"i4","texte":"No conozco ___ nadie más"}]},{"enonce":"Touche l’**heure** à laquelle Irene arrive à Tolède.","aide":"Elle arrive « a las… ».","type":"zone","document":"carta","multiple":false},{"enonce":"Complète la phrase d’Irene.","aide":"L’heure : *a las*. Le transport : *en tren*.","type":"trous","segments":["Llego ",0," las diez, ",1," tren."],"banque":["a","por","en","de"]},{"enonce":"Pourquoi Irene écrit-elle « Quiero mucho **a** mis abuelos » ?","aide":"Avec *querer*, tout dépend de ce qui suit : une chose ou une personne ?","type":"choix","options":[{"id":"a","texte":"Le complément est une personne précise"},{"id":"b","texte":"On indique l’heure"},{"id":"c","texte":"Le verbe *querer* impose toujours *a*"},{"id":"d","texte":"Il y a un mouvement vers un lieu"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c0"}},"explication":"*A* devant **mis abuelos**, **su perro**, **nadie** ; pas de *a* après **tener** ni pour **un compañero** (n’importe lequel)."},{"cle":{"type":"zone","ids":["m15"]},"explication":"**diez** : *llego a las diez*, l’heure se dit avec *a las*."},{"cle":{"type":"trous","trous":[["a"],["en"]]},"affichage":"a · en","explication":"**a las diez, en tren**."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Personne précise** : *querer a alguien* = aimer quelqu’un ; *querer algo* = vouloir quelque chose."}]$ex$::jsonb),
