"multiple":false},{"enonce":"Que veut dire Hugo avec « Lucía me llama **dentro de** una hora » ?","aide":"*Dentro de* + durée annonce un délai dans le futur.","type":"choix","options":[{"id":"a","texte":"Lucía m’appelle pendant une heure"},{"id":"b","texte":"Lucía m’a appelé il y a une heure"},{"id":"c","texte":"Lucía m’appelle depuis une heure"},{"id":"d","texte":"Lucía m’appelle dans une heure"}],"multiple":false}]}$ex$::jsonb,
