  ('06e09431-d14d-5b9e-8e35-c93c22cbb919'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Sara se présente en classe","competence":"comprendre-langue","situation":"Sara, une élève chilienne, se présente à sa nouvelle classe. Tu relèves ce qu’elle dit de sa vie à Madrid et de son français.","documents":[{"id":"pres","type":"texte","genre":"lettre","titre":"Presentación de Sara","blocs":["Hola, me llamo Sara y soy chilena.","Vivo en Madrid desde hace dos años. En mi clase hay veinte alumnos.","Llevo un año estudiando francés: empecé hace doce meses."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui veut dire « il y a » au sens de « il existe ».","aide":"Ce n’est pas *hace* : il s’agit de dire que des élèves existent dans la classe.","type":"zone","document":"pres","multiple":false},{"enonce":"Depuis combien d’années Sara vit-elle à Madrid ?","aide":"Repère *desde hace* dans le texte.","type":"nombre","unite":"ans"},{"enonce":"Complète : « Sara a commencé le français il y a douze mois. »","aide":"« Il y a » + durée, pour un moment passé, se dit avec le verbe *hacer*.","type":"trous","segments":["Sara empezó a estudiar francés ",0," doce meses."],"banque":["desde","hay","hace","dentro"]},{"enonce":"Que dit Sara avec « Llevo un año estudiando francés » ?","aide":"*Llevar* + durée + gérondif : l’action est toujours en cours.","type":"choix","options":[{"id":"a","texte":"Elle a arrêté le français il y a un an"},{"id":"b","texte":"Elle étudie le français pendant un an seulement"},{"id":"c","texte":"Elle étudie le français depuis un an et continue"},{"id":"d","texte":"Elle commencera le français dans un an"}],"multiple":false}]}$ex$::jsonb,
