  ('06e09431-d14d-5b9e-8e35-c93c22cbb919'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La frise de Lucía à Séville","competence":"se-reperer-temps","situation":"Lucía s’est installée à Séville. Sur sa frise personnelle, elle note ses étapes importantes. Nous sommes en 2026.","documents":[{"id":"frise","type":"frise","titre":"La vie de Lucía à Séville","debut":2018,"fin":2026,"pas":1,"evenements":[{"id":"z1","date":2019,"nom":"Llega a Sevilla"},{"id":"z2","date":2022,"nom":"Entra al instituto"},{"id":"z3","date":2024,"nom":"Empieza la guitarra"}],"source":"Frise écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’événement qui date de « **hace cuatro años** » (nous sommes en 2026).","aide":"Retranche quatre ans à 2026.","type":"zone","document":"frise","multiple":false},{"enonce":"Depuis combien d’années Lucía vit-elle à Séville ?","aide":"Compte les années entre son arrivée et 2026.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase avec la tournure la plus idiomatique.","aide":"*Llevar* + durée + gérondif.","type":"trous","segments":["Lucía lleva siete años ",0," en Sevilla."],"banque":["vive","vivido","vivir","viviendo"]},{"enonce":"Remets en ordre : « Cela fait sept ans que Lucía vit à Séville. » La phrase commence par *Hace*.","aide":"*Hace* + durée + *que* + présent.","type":"ordre","items":[{"id":"a","texte":"que"},{"id":"b","texte":"siete años"},{"id":"c","texte":"en Sevilla"},{"id":"d","texte":"Lucía vive"},{"id":"e","texte":"Hace"}]},{"enonce":"Associe chaque expression à son sens.","aide":"Distingue le moment passé, la durée qui continue et le futur.","type":"association","gauche":[{"id":"g0","texte":"hace dos años"},{"id":"g1","texte":"desde hace dos años"},{"id":"g2","texte":"al cabo de dos días"},{"id":"g3","texte":"dentro de dos días"}],"droite":[{"id":"d0","texte":"Au bout de deux jours"},{"id":"d1","texte":"Depuis deux ans (durée en cours)"},{"id":"d2","texte":"Il y a deux ans (moment passé)"},{"id":"d3","texte":"Dans deux jours (futur)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**2022** : 2026 − 4 = 2022, Lucía entre au lycée (*Entra al instituto*)."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 ans","explication":"2026 − 2019 = **7 ans**."},{"cle":{"type":"trous","trous":[["viviendo"]]},"affichage":"viviendo","explication":"**viviendo** : *llevar* + durée + gérondif = « ça fait sept ans qu’elle vit »."},{"cle":{"type":"ordre","ids":["e","b","a","d","c"]},"explication":"**Hace siete años que Lucía vive en Sevilla** : le verbe reste au présent car la situation continue."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"**hace** = moment passé, **desde hace** = durée en cours, **al cabo de** = au bout de, **dentro de** = délai futur."}]$ex$::jsonb),
  ('06e09431-d14d-5b9e-8e35-c93c22cbb919'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Nico écrit d’Oaxaca : calendrier et lettre","competence":"analyser-document","situation":"Nico voyage au Mexique. Il écrit à Rosa et tient un petit calendrier de son séjour. Le jour 15 est le jour où il écrit sa lettre.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Nico","blocs":["Querida Rosa:","Te escribo desde Oaxaca. Llegué hace dos semanas y ya estoy mejor de la fiebre.","Ayer fui al médico: cuando por fin me recibió, yo llevaba una hora esperando.","Dentro de una semana vuelvo a Madrid. ¡Un abrazo! Nico"],"source":"Lettre écrite pour l’exercice"},{"id":"cal","type":"tableau","titre":"Calendrier du séjour de Nico","colonnes":["Día","Qué pasa"],"lignes":[["1","Llegada a Oaxaca"],["8","Empieza la fiebre"],["15","Hoy: Nico escribe a Rosa"],["22","Vuelo a Madrid"]],"source":"Calendrier écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’événement qui date de « **hace una semana** » (le jour 15 est aujourd’hui).","aide":"Retranche 7 jours au jour 15.","type":"zone","document":"cal","multiple":false},{"enonce":"D’après le calendrier, quelle phrase de Nico est exacte ?","aide":"La fièvre commence le jour 8, et nous sommes au jour 15.","type":"choix","options":[{"id":"a","texte":"Llevo una semana con fiebre."},{"id":"b","texte":"Llevo dos semanas con fiebre."},{"id":"c","texte":"Llevo tres días con fiebre."},{"id":"d","texte":"Llevo un mes con fiebre."}],"multiple":false},{"enonce":"Touche le mot qui annonce un **délai dans le futur** (« dans une semaine »).","aide":"Il commence par *d* et s’emploie avec *de* + durée.","type":"zone","document":"carta","multiple":false},{"enonce":"Remets en ordre : « Cela fait une semaine que j’ai de la fièvre. » La phrase commence par *Hace*.","aide":"*Hace* + durée + *que* + présent.","type":"ordre","items":[{"id":"a","texte":"una semana"},{"id":"b","texte":"tengo"},{"id":"c","texte":"Hace"},{"id":"d","texte":"que"},{"id":"e","texte":"fiebre"}]},{"enonce":"Complète la phrase de la lettre, au passé.","aide":"Au passé, la durée en cours se met à l’imparfait.","type":"trous","segments":["Cuando el médico me recibió, yo ",0," una hora esperando."],"banque":["llevé","llevaba","llevo","llevaré"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"**Jour 8** : 15 − 7 = 8, c’est le début de la fièvre."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Una semana** : du jour 8 au jour 15, sept jours ; *llevar* + durée dit que ça continue."},{"cle":{"type":"zone","ids":["m31"]},"explication":"**Dentro** : *dentro de una semana* = dans une semaine, le jour 22 au calendrier."},{"cle":{"type":"ordre","ids":["c","a","d","b","e"]},"explication":"**Hace una semana que tengo fiebre** : la fièvre continue, donc le présent."},{"cle":{"type":"trous","trous":[["llevaba"]]},"affichage":"llevaba","explication":"**llevaba** : *llevaba una hora esperando* = « ça faisait une heure que j’attendais »."}]$ex$::jsonb),
