   $ex${"titre":"Frise et ballade : à qui parle Villon ?","competence":"analyser-document","situation":"Samir prépare une fiche sur la poésie avant 1700. Il a une frise de repères et les quatre premiers vers d’un poème célèbre du XVe siècle, la Ballade des pendus.","documents":[{"id":"frise","type":"frise","titre":"Quelques repères","debut":1100,"fin":1700,"pas":100,"periodes":[{"id":"z1","debut":1170,"fin":1250,"nom":"Roman de Renart","teinte":"ambre"},{"id":"z2","debut":1668,"fin":1694,"nom":"Fables de La Fontaine","teinte":"bleu"}],"evenements":[{"id":"z3","date":1549,"nom":"Défense et illustration"},{"id":"z4","date":1558,"nom":"Les Regrets"}]},{"id":"ballade","type":"texte","genre":"poeme","titre":"Ballade des pendus","blocs":["Frères humains qui après nous vivez,","N’ayez les cœurs contre nous endurcis,","Car, si pitié de nous pauvres avez,","Dieu en aura plus tôt de vous mercis."],"source":"François Villon, Ballade des pendus (XVe siècle), orthographe modernisée"}],"questions":[{"enonce":"Sur la frise, touche la période pendant laquelle les branches du Roman de Renart ont été composées.","aide":"Cherche la période qui commence en 1170.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la parution de *Défense et illustration de la langue française* de celle des *Regrets* ?","aide":"Soustrais la date la plus ancienne de la plus récente.","type":"nombre","unite":"ans"},{"enonce":"Laquelle de ces périodes appartient entièrement au XVIIe siècle ? Touche-la.","aide":"Le XVIIe siècle va de 1601 à 1700.","type":"zone","document":"frise","multiple":false},{"enonce":"Dans le poème, à qui Villon s’adresse-t-il ? Touche les deux mots qui nomment ses destinataires.","aide":"Regarde le tout début du premier vers.","type":"zone","document":"ballade","multiple":true},{"enonce":"Pourquoi ce poème rompt-il avec la poésie courtoise ?","aide":"La courtoisie, c’est la dame idéalisée. Ici, de qui et de quoi parle-t-on ?","type":"choix","options":[{"id":"a","texte":"Il célèbre une dame inaccessible qu’un chevalier doit servir"},{"id":"b","texte":"Il parle d’hommes pendus et réclame la pitié, en langue directe"},{"id":"c","texte":"Il est écrit en latin pour s’adresser aux savants de l’époque"},{"id":"d","texte":"Il raconte la ruse d’un animal qui dupe un puissant du royaume"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Les branches du **Roman de Renart** sont composées **entre 1170 et 1250 environ**."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 ans","explication":"1558 − 1549 = **9** ans."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Les *Fables* de La Fontaine, publiées de **1668 à 1694**, appartiennent au **XVIIe siècle** ; le Roman de Renart est du XIIe-XIIIe."},{"cle":{"type":"zone","ids":["m0","m1"]},"explication":"Il s’adresse aux vivants : **« Frères humains »**. Il parle au nom des pendus, pour demander la pitié."},{"cle":{"type":"choix","ids":["b"]},"explication":"Villon écrit la **mort** et la **pitié** dans une langue directe : c’est l’inverse de l’amour courtois, de la dame inaccessible et du service du chevalier."}]$ex$::jsonb),
  ('84370f35-aba7-51fd-91e9-cf10e3556e73'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quatre voix, quatre siècles","competence":"analyser-texte","situation":"Quatre poètes imaginaires parlent de leur art. Pour l’exercice, leurs paroles ont été mélangées : à toi de retrouver à quelle époque appartient chacun.","documents":[{"id":"voix","type":"texte","genre":"source","titre":"Quatre poètes, quatre siècles","blocs":["Je ne fais pas de vers pour plaire : j’en fais pour que le juge rougisse et pour qu’un innocent ne monte plus à l’échafaud.","Ma dame est si haute que je n’ose lui parler ; je chante sous sa tour, et mon seul service est de l’aimer sans espoir.","J’ai compté mes douze syllabes, soigné mes rimes riches et respecté le genre : chez moi, la règle fait la beauté.","J’écris en français, non en latin : notre langue vaut celle des Anciens, et je la rends savante à force de travail."],"source":"Textes écrits pour l’exercice"}],"questions":[{"enonce":"Range les quatre extraits du plus ancien au plus récent (les numéros sont ceux des paragraphes).","aide":"Cherche d’abord celui qui chante sous une tour : il appartient au plus ancien des siècles.","type":"ordre","items":[{"id":"a","texte":"Extrait 1"},{"id":"b","texte":"Extrait 4"},{"id":"c","texte":"Extrait 2"},{"id":"d","texte":"Extrait 3"}]},{"enonce":"Dans l’extrait 2, touche le mot qui dit la place du chevalier auprès de sa dame.","aide":"Le chevalier est « au… » de la dame.","type":"zone","document":"voix","multiple":false},{"enonce":"Dans l’extrait 4, touche le mot qui montre la revendication de la Pléiade.","aide":"Quelle langue le poète choisit-il, plutôt que le latin ?","type":"zone","document":"voix","multiple":false},{"enonce":"Relie chaque extrait à celui qui pourrait le prononcer.","aide":"Aide-toi du classement que tu viens de faire.","type":"association","gauche":[{"id":"g0","texte":"Extrait 1"},{"id":"g1","texte":"Extrait 2"},{"id":"g2","texte":"Extrait 3"},{"id":"g3","texte":"Extrait 4"}],"droite":[{"id":"d0","texte":"La Fontaine et son siècle de la règle"},{"id":"d1","texte":"Un trouvère ou un troubadour"},{"id":"d2","texte":"Un auteur des Lumières"},{"id":"d3","texte":"Du Bellay et la Pléiade"}]},{"enonce":"Quelle constante relie pourtant ces quatre poètes, malgré les siècles ?","aide":"Pense aux trois chantiers du poète : rythme, son, image.","type":"choix","options":[{"id":"a","texte":"Ils travaillent la langue pour la rendre plus dense que la prose"},{"id":"b","texte":"Ils refusent tous le rythme pour laisser parler leurs émotions seules"},{"id":"c","texte":"Ils écrivent tous en latin pour être lus par les savants du royaume"},{"id":"d","texte":"Ils parlent tous de la même dame, qu’aucun des quatre n’a nommée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["c","b","d","a"]},"explication":"Extrait 2 : amour courtois, **Moyen Âge** ; extrait 4 : le français savant, **Renaissance** ; extrait 3 : la règle, **XVIIe** ; extrait 1 : la poésie comme arme, **XVIIIe**."},{"cle":{"type":"zone","ids":["m46"]},"explication":"Dans l’amour courtois, le chevalier est **au service** de sa dame idéalisée."},{"cle":{"type":"zone","ids":["m77"]},"explication":"La Pléiade veut écrire une poésie savante en **français** plutôt qu’en latin."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"Extrait 1 : les **Lumières** ; extrait 2 : un **trouvère** ; extrait 3 : le **XVIIe**, siècle de **La Fontaine** et de la règle ; extrait 4 : **Du Bellay** et la Pléiade."},{"cle":{"type":"choix","ids":["a"]},"explication":"Quel que soit le siècle, la poésie **travaille la langue** (rythme, son, image) pour la rendre plus dense que la prose."}]$ex$::jsonb),
  ('a8d8b644-7546-571f-b461-ca81ad148e9e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Compter les pas d’un quatrain","competence":"manier-langue","situation":"Pour son club d’écriture, Inès a composé un petit quatrain sur un matin de printemps. Elle te demande de vérifier ses vers : combien de syllabes, quelles rimes ?","documents":[{"id":"matin","type":"texte","genre":"poeme","titre":"Matin","blocs":["Le soleil dort sur la colline,","Un chant d’oiseau perce la brume,","Un souffle doux qui la câline,","Et tout le matin se parfume."],"source":"Vers écrits pour l’exercice"}],"questions":[{"enonce":"Combien de syllabes compte le premier vers, « Le soleil dort sur la colline » ? (Le e muet final ne compte pas.)","aide":"Compte à voix basse : Le-so-leil-dort… N’oublie pas que « soleil » fait deux syllabes.","type":"nombre"},{"enonce":"Relie chaque mètre à son nombre de syllabes.","aide":"Le préfixe du mot te met sur la voie : octo-, déca-… et l’alexandrin est le plus long.","type":"association","gauche":[{"id":"g0","texte":"Octosyllabe"},{"id":"g1","texte":"Décasyllabe"},{"id":"g2","texte":"Alexandrin"}],"droite":[{"id":"d0","texte":"10 syllabes"},{"id":"d1","texte":"12 syllabes"},{"id":"d2","texte":"8 syllabes"}]},{"enonce":"Touche le mot qui rime avec « colline », à la fin du vers 3.","aide":"Cherche un mot qui finit par le même son, au bout d’un vers.","type":"zone","document":"matin","multiple":false},{"enonce":"Quel est le schéma des rimes de ce quatrain ?","aide":"Note A pour le premier son final, B pour le deuxième, et suis les vers dans l’ordre.","type":"choix","options":[{"id":"a","texte":"ABCD, aucune rime"},{"id":"b","texte":"ABAB, rimes croisées"},{"id":"c","texte":"AABB, rimes suivies"},{"id":"d","texte":"ABBA, rimes embrassées"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"Le / so / leil / dort / sur / la / co / li(ne) : **8** syllabes, c’est un **octosyllabe**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Octosyllabe : **8** ; décasyllabe : **10** ; alexandrin : **12**, coupé en deux hémistiches de 6."},{"cle":{"type":"zone","ids":["m18"]},"explication":"**Câline** rime avec **colline** : les deux finissent par le son [lin]. Le troisième vers répond au premier."},{"cle":{"type":"choix","ids":["b"]},"explication":"colline (A), brume (B), câline (A), parfume (B) : le schéma est **ABAB**, des **rimes croisées**."}]$ex$::jsonb),
  ('a8d8b644-7546-571f-b461-ca81ad148e9e'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Les figures d’un rivage","competence":"analyser-texte","situation":"Noé doit repérer les procédés d’un court poème écrit pour la classe. Il n’a pas le droit de dire « c’est joli » : il doit nommer ce que le texte fait.","documents":[{"id":"rivage","type":"texte","genre":"poeme","titre":"Le rivage","blocs":["Sur le sable, le soir, un souffle sourd soupire ;","La mer est comme un miroir où tremble le ciel ;","Un silence assourdissant monte du rivage","Et l’eau, qui se souvient, murmure sa prière."],"source":"Vers écrits pour l’exercice"}],"questions":[{"enonce":"Au vers 2, touche le petit mot qui introduit la comparaison.","aide":"Il rapproche deux choses : la mer et un miroir.","type":"zone","document":"rivage","multiple":false},{"enonce":"Au vers 3, touche les deux mots de sens contraire accolés.","aide":"L’un parle d’une absence de bruit, l’autre d’un bruit qui empêche d’entendre.","type":"zone","document":"rivage","multiple":true},{"enonce":"Au vers 1, la répétition du son [s] (sable, soir, souffle, sourd, soupire) est…","aide":"Le son [s] est-il une voyelle ou une consonne ?","type":"choix","options":[{"id":"a","texte":"Une assonance, car elle répète une voyelle"},{"id":"b","texte":"Une anaphore, car elle répète un mot en début de vers"},{"id":"c","texte":"Un rejet, car le sens déborde sur le vers suivant"},{"id":"d","texte":"Une allitération, car elle répète une consonne"}],"multiple":false},{"enonce":"« Et l’eau, qui se souvient, murmure sa prière » : quelle figure prête une conduite humaine à une chose ?","aide":"L’eau a une mémoire, elle prie : à qui ressemble-t-elle ?","type":"choix","options":[{"id":"a","texte":"La litote, qui dit moins pour suggérer davantage"},{"id":"b","texte":"La personnification, qui prête une conduite humaine"},{"id":"c","texte":"L’allégorie, qui figure une idée abstraite par un personnage"},{"id":"d","texte":"L’hyperbole, qui exagère pour mieux frapper le lecteur"}],"multiple":false},{"enonce":"Ce poème compte quatre vers : comment s’appelle une strophe de quatre vers ?","aide":"Le mot commence comme « quatre ».","type":"texte","placeholder":"un mot"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"Le mot **comme** est l’outil de la **comparaison** : sans lui, on aurait une métaphore."},{"cle":{"type":"zone","ids":["m20","m21"]},"explication":"« Silence assourdissant » est un **oxymore** : deux mots contraires accolés."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le [s] est une consonne : c’est une **allitération**. L’assonance répète une voyelle."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’eau qui se souvient et prie est une **personnification** : on prête une conduite humaine à une chose."},{"cle":{"type":"texte","acceptes":["quatrain","un quatrain"]},"affichage":"quatrain","explication":"Une strophe de quatre vers est un **quatrain**."}]$ex$::jsonb),
  ('a8d8b644-7546-571f-b461-ca81ad148e9e'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une rose et ses syllabes","competence":"manier-langue","situation":"Mathis veut analyser les premiers vers d’une ode célèbre de la Renaissance. Il a sous les yeux la strophe et le rappel des règles du e muet.","documents":[{"id":"ode","type":"texte","genre":"poeme","titre":"Mignonne, allons voir si la rose","blocs":["Mignonne, allons voir si la rose","Qui ce matin avait déclose","Sa robe de pourpre au soleil,","A point perdu cette vesprée","Les plis de sa robe pourprée,","Et son teint au vôtre pareil."],"source":"Pierre de Ronsard, Odes (XVIe siècle), orthographe modernisée"},{"id":"emuet","type":"tableau","titre":"Le e muet dans le vers","colonnes":["Le cas du e muet","Compte-t-il ?"],"lignes":[["Devant une consonne","Oui"],["Devant une voyelle (élision)","Non"],["En fin de vers","Non"]],"enteteLignes":true}],"questions":[{"enonce":"Combien de syllabes compte le premier vers du poème ? (Dans « Mignonne allons », le e est devant une voyelle.)","aide":"Le e de « Mignonne » est devant une voyelle : il disparaît. Celui de « rose » est en fin de vers.","type":"nombre"},{"enonce":"Cette strophe compte six vers : comment s’appelle une strophe de six vers ?","aide":"Relis le tableau des strophes dans ton cours : 2, 3, 4, 5, 6, 8…","type":"texte","placeholder":"un mot"},{"enonce":"Aux vers 4 et 5, « vesprée » et « pourprée » riment. Quelle est la richesse de cette rime ?","aide":"Compte les sons communs à la fin des deux mots : [p], [r], [é]…","type":"choix","options":[{"id":"a","texte":"Pauvre : un seul son commun"},{"id":"b","texte":"Suffisante : deux sons communs"},{"id":"c","texte":"Riche : trois sons communs ou plus"}],"multiple":false},{"enonce":"Classe les mots à la rime de la strophe : rime féminine (finissant par un e muet) ou masculine.","aide":"Regarde la dernière lettre : un e muet à la fin ?","type":"categories","categories":[{"id":"c0","texte":"Rime féminine"},{"id":"c1","texte":"Rime masculine"}],"items":[{"id":"i0","texte":"soleil"},{"id":"i1","texte":"pourprée"},{"id":"i2","texte":"vesprée"},{"id":"i3","texte":"pareil"},{"id":"i4","texte":"rose"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"Mi / gno / n’al / lons / voir / si / la / ro(se) : **8** syllabes, c’est un **octosyllabe**."},{"cle":{"type":"texte","acceptes":["sizain","un sizain"]},"affichage":"sizain","explication":"Une strophe de six vers est un **sizain**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les deux mots ont en commun [p] + [r] + [é] : **trois sons**, la rime est **riche**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c0"}},"explication":"Les rimes **féminines** finissent par un e muet (rose, vesprée, pourprée) ; les **masculines** non (soleil, pareil)."}]$ex$::jsonb),
  ('b200bdee-fd6d-5a3f-9206-ec78ec85c43b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La distribution de la saynète","competence":"comprendre-langue","situation":"La classe monte une petite saynète tirée du Roman de Renart. Voici l’affiche avec les costumes de chaque rôle : à toi de reconnaître qui joue qui.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Le procès de Renart","sousTitre":"Saynète de la classe de 2de","emoji":"🦊","teinte":"ambre","lignes":[{"texte":"Noble le lion","valeur":"Couronne en carton doré","id":"z1"},{"texte":"Ysengrin le loup","valeur":"Grande cape grise, dents pointues","id":"z2"},{"texte":"Chantecler le coq","valeur":"Plumes rouges, bec haut","id":"z3"},{"texte":"Renart le goupil","valeur":"Queue rousse, air malin","id":"z4"}],"pied":"Auditorium — vendredi"}],"questions":[{"enonce":"Touche l’animal qui joue le roi.","aide":"Regarde le costume : quel accessoire est celui d’un souverain ?","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche le grand baron brutal, rival principal de Renart.","aide":"C’est un animal féroce, qui n’aime pas le goupil.","type":"zone","document":"affiche","multiple":false},{"enonce":"Relie chaque animal à son rôle dans la société du Roman de Renart.","aide":"Un animal = un rang dans une société féodale.","type":"association","gauche":[{"id":"g0","texte":"Noble le lion"},{"id":"g1","texte":"Ysengrin le loup"},{"id":"g2","texte":"Chantecler le coq"},{"id":"g3","texte":"Renart le goupil"}],"droite":[{"id":"d0","texte":"Le grand baron brutal"},{"id":"d1","texte":"Un naïf plein de vanité"},{"id":"d2","texte":"Le roi"},{"id":"d3","texte":"Le petit, qui n’a que sa ruse"}]}]}$ex$::jsonb,
