  ('b200bdee-fd6d-5a3f-9206-ec78ec85c43b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Renart flatte Chantecler","competence":"analyser-texte","situation":"Voici un épisode écrit pour l’exercice, dans l’esprit du Roman de Renart. Observe qui rit, qui se fait avoir, et comment.","documents":[{"id":"episode","type":"texte","genre":"recit","titre":"Sur le fumier","blocs":["Chantecler, perché sur son fumier, gonflait ses plumes.","— Quelle voix magnifique, mon cousin ! dit Renart en s’inclinant. Votre père chantait mieux encore, les yeux fermés… mais vous, je gage que vous le surpassez.","Ravi, le coq ferma les yeux et ouvrit le bec. D’un bond, le goupil l’attrapa par le cou et courut vers la forêt.","— Crie donc à ceux qui te poursuivent que tu emportes ta proie ! lança Chantecler d’une voix étranglée. Renart, trop fier, ouvrit la gueule pour crier : le coq se libéra et s’envola sur une branche."],"source":"Texte écrit pour l’exercice, d’après un épisode du Roman de Renart"}],"questions":[{"enonce":"Touche les deux mots par lesquels Renart flatte le coq.","aide":"Cherche les compliments dans la réplique de Renart.","type":"zone","document":"episode","multiple":true},{"enonce":"Touche le mot qui montre que le coq se laisse prendre par vanité.","aide":"Quel mot dit l’effet du compliment sur le coq ?","type":"zone","document":"episode","multiple":false},{"enonce":"Remets les moments du récit dans l’ordre.","aide":"Suis les quatre paragraphes dans l’ordre.","type":"ordre","items":[{"id":"a","texte":"Le coq se libère et s’envole"},{"id":"b","texte":"Le coq ferme les yeux"},{"id":"c","texte":"Renart flatte le coq"},{"id":"d","texte":"Le goupil attrape Chantecler"}]},{"enonce":"Quel ressort comique domine dans cet épisode ?","aide":"Qui gagne à la fin ? Est-ce celui qu’on attendait ?","type":"choix","options":[{"id":"a","texte":"Le comique de répétition : la même phrase revient sans cesse"},{"id":"b","texte":"Le comique de mots : un jeu de mots sur le nom du coq"},{"id":"c","texte":"Le comique de situation : la ruse se retourne contre le ruseur"},{"id":"d","texte":"Le comique de caractère : une longue dispute sur le chant"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m33"]},"explication":"Renart flatte Chantecler avec **magnifique** et **surpassez** : la ruse commence par un compliment."},{"cle":{"type":"zone","ids":["m34"]},"explication":"**Ravi** : le coq, flatté, ferme les yeux. Chantecler est un naïf plein de **vanité**."},{"cle":{"type":"ordre","ids":["c","b","d","a"]},"explication":"Flatterie, puis les yeux fermés, puis la prise, puis la **ruse retournée** : le trompeur est trompé."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le comique repose sur la **situation** : les ruses, les coups reçus, le **trompeur trompé**. Il ressemble à une farce."}]$ex$::jsonb),
  ('b200bdee-fd6d-5a3f-9206-ec78ec85c43b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un tribunal où tout s’achète","competence":"analyser-document","situation":"Dans ce procès imaginaire, écrit pour l’exercice, Renart comparaît devant le roi Noble. Qui est jugé, au fond : Renart… ou la justice ?","documents":[{"id":"proces","type":"texte","genre":"recit","titre":"Le procès de Renart","blocs":["Le roi Noble tint sa cour. Ysengrin se leva : — Sire, Renart a mangé mes poules et trompé mes enfants ! Je demande qu’on le pende.","Renart s’avança, une patte posée sur un pot de miel. — Sire, dit-il, je ne suis qu’un humble pèlerin et je ne fais que prier pour la paix du royaume.","Le roi goûta le miel, ferma les yeux et déclara, très solennel, que l’accusé était un pieux animal, victime de la jalousie du loup.","Ysengrin gronda, montra les crocs et rappela qu’en ce royaume, le plus fort avait toujours raison."],"source":"Texte écrit pour l’exercice, à la manière du Roman de Renart"},{"id":"parodie","type":"tableau","titre":"Le modèle sérieux et sa parodie","colonnes":["Le modèle sérieux","Ce que Renart en fait"],"lignes":[["La chanson de geste","Des ruses de goupil à la place des combats héroïques"],["Le roman courtois","Des animaux à la place des chevaliers"],["Le procès féodal","Un tribunal grotesque où l’on juge un renard dans les formes"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’objet par lequel Renart obtient la faveur du roi.","aide":"Que tient Renart dans sa patte, pour amadouer le roi ?","type":"zone","document":"proces","multiple":false},{"enonce":"Touche le mot par lequel Renart se couvre d’une apparence religieuse.","aide":"Il se présente comme quelqu’un qui voyage pour prier.","type":"zone","document":"proces","multiple":false},{"enonce":"Relie chaque cible de la satire à ce que le procès en montre.","aide":"Pense au miel, au pèlerin, puis au dernier paragraphe, celui des crocs.","type":"association","gauche":[{"id":"g0","texte":"La justice"},{"id":"g1","texte":"La religion"},{"id":"g2","texte":"La force"}],"droite":[{"id":"d0","texte":"Elle sert de couverture"},{"id":"d1","texte":"Elle tient lieu de droit"},{"id":"d2","texte":"Elle se laisse acheter"}]},{"enonce":"Dans le tableau, touche la case qui dit ce que Renart fait du procès féodal : c’est le modèle que cette scène parodie.","aide":"Cherche la ligne « Le procès féodal », puis la colonne de droite.","type":"zone","document":"parodie","multiple":false},{"enonce":"Renart est-il un héros exemplaire dans le Roman de Renart ?","aide":"Relis la scène : le loup et le roi sont-ils plus vertueux que le goupil ?","type":"choix","options":[{"id":"a","texte":"Oui : il combat les puissants au nom de la justice et de la vérité"},{"id":"b","texte":"Oui : il incarne la vertu du faible contre la brutalité des puissants"},{"id":"c","texte":"Non : il est la seule bête mauvaise de la forêt et ses juges sont justes"},{"id":"d","texte":"Non : il est menteur, voleur et cruel, mais ses victimes ne valent pas mieux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m35"]},"explication":"Le **miel** achète le verdict : la satire vise une **justice** qu’on peut acheter."},{"cle":{"type":"zone","ids":["m44"]},"explication":"Renart se dit **pèlerin** : la **religion** lui sert de couverture, c’est un autre point visé par la satire."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"La justice s’**achète** (le miel), la religion sert de **couverture** (le pèlerin), la force **tient lieu de droit** (« le plus fort avait toujours raison »)."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"La scène parodie le **procès féodal** : un **tribunal grotesque** où l’on juge un renard dans les formes."},{"cle":{"type":"choix","ids":["d"]},"explication":"Renart n’est pas un héros : il est **menteur, voleur et cruel**. Mais ses victimes le sont autant que lui, et ce sont elles qui détiennent le **pouvoir**."}]$ex$::jsonb),
  ('49965686-6d82-542f-9855-8b1bc14db7a5'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les mots à la rime d’un sonnet","competence":"analyser-document","situation":"Chloé a noté, vers par vers, le dernier mot du célèbre sonnet de Du Bellay « Heureux qui, comme Ulysse » (*Les Regrets*, 1558). À elle de retrouver la structure.","documents":[{"id":"rimes","type":"tableau","titre":"Le mot à la fin de chacun des 14 vers","colonnes":["Vers","Mot à la rime"],"lignes":[[1,"voyage"],[2,"toison"],[3,"raison"],[4,"âge"],[5,"village"],[6,"saison"],[7,"maison"],[8,"davantage"],[9,"aïeux"],[10,"audacieux"],[11,"fine"],[12,"latin"],[13,"Palatin"],[14,"angevine"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui rime avec « voyage » dans le premier quatrain.","aide":"Cherche un mot en -âge dans les quatre premières lignes.","type":"zone","document":"rimes","multiple":false},{"enonce":"Quel schéma de rimes les deux quatrains suivent-ils ?","aide":"Lis les quatre premiers mots à la rime : voyage, toison, raison, âge. Quel est le motif ?","type":"choix","options":[{"id":"a","texte":"ABAB ABAB"},{"id":"b","texte":"ABBA ABBA"},{"id":"c","texte":"ABBA CDDC"},{"id":"d","texte":"AABB CCDD"}],"multiple":false},{"enonce":"Touche le mot qui termine le sonnet, dans la chute.","aide":"La chute est le dernier vers : le quatorzième.","type":"zone","document":"rimes","multiple":false},{"enonce":"Complète : un sonnet compte ___ vers, répartis en deux quatrains puis deux ___.","aide":"Compte les lignes du tableau.","type":"trous","segments":["Un sonnet compte ",0," vers, répartis en deux quatrains puis deux ",1,"."],"banque":["quatorze","douze","tercets","distiques"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"**Âge** (vers 4) rime avec **voyage** (vers 1) : c’est le A de ABBA."},{"cle":{"type":"choix","ids":["b"]},"explication":"voyage (A), toison (B), raison (B), âge (A) : **ABBA** ; village, saison, maison, davantage : **ABBA** encore."},{"cle":{"type":"zone","ids":["r13c1"]},"explication":"Le dernier mot est **angevine** : la **chute** condense le poème, la douceur du pays natal."},{"cle":{"type":"trous","trous":[["quatorze"],["tercets"]]},"affichage":"quatorze · tercets","explication":"Un sonnet compte **quatorze** vers : deux quatrains (8 vers) puis deux **tercets** (6 vers)."}]$ex$::jsonb),
  ('49965686-6d82-542f-9855-8b1bc14db7a5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le mal du pays d’un poète à Rome","competence":"analyser-texte","situation":"Du Bellay est à Rome, loin de son village angevin. Voici le début et la fin de son sonnet : lis-les comme un raisonnement.","documents":[{"id":"q1","type":"texte","genre":"poeme","titre":"Le premier quatrain","blocs":["Heureux qui, comme Ulysse, a fait un beau voyage,","Ou comme cestuy-là qui conquit la toison,","Et puis est retourné, plein d’usage et raison,","Vivre entre ses parents le reste de son âge !"],"source":"Joachim du Bellay, Les Regrets (1558), sonnet 31 (orthographe de « cestuy-là » conservée)"},{"id":"t2","type":"texte","genre":"poeme","titre":"Le dernier tercet","blocs":["Plus mon Loire gaulois que le Tibre latin,","Plus mon petit Liré que le mont Palatin,","Et plus que l’air marin la douceur angevine."],"source":"Joachim du Bellay, Les Regrets (1558), sonnet 31"}],"questions":[{"enonce":"Touche le nom du héros antique que le poète prend pour modèle.","aide":"C’est le héros d’un grand voyage, qui finit par rentrer chez lui.","type":"zone","document":"q1","multiple":false},{"enonce":"À quoi sert ici le voyage d’Ulysse ?","aide":"Où est Du Bellay quand il écrit ? Regrette-t-il Rome ou son village ?","type":"choix","options":[{"id":"a","texte":"À dire le mal du pays d’un homme réel, exilé à Rome"},{"id":"b","texte":"À faire l’éloge de la grandeur de la ville de Rome"},{"id":"c","texte":"À raconter les exploits d’un guerrier devant Troie"},{"id":"d","texte":"À enseigner aux lecteurs la navigation sur la Méditerranée"}],"multiple":false},{"enonce":"Dans le dernier tercet, touche les deux fleuves que le poète oppose.","aide":"L’un est celui de son pays, l’autre celui de Rome.","type":"zone","document":"t2","multiple":true},{"enonce":"Relie chaque élément romain à ce que le poète lui préfère.","aide":"Le tercet fonctionne par couples : « Plus… que… ».","type":"association","gauche":[{"id":"g0","texte":"Le Tibre latin"},{"id":"g1","texte":"Le mont Palatin"},{"id":"g2","texte":"L’air marin"}],"droite":[{"id":"d0","texte":"La douceur angevine"},{"id":"d1","texte":"Le petit Liré"},{"id":"d2","texte":"Le Loire gaulois"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**Ulysse** est le héros qui revient chez lui après un long voyage : Du Bellay se compare à lui."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le voyage antique **sert à dire le mal du pays** d’un homme réel : Du Bellay, à Rome, regrette son village."},{"cle":{"type":"zone","ids":["m2","m6"]},"explication":"Le **Loire** gaulois (son pays) est opposé au **Tibre** latin (Rome)."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Chaque vers du tercet **oppose la grandeur romaine à la douceur du village natal** : Tibre / Loire, Palatin / Liré, air marin / douceur angevine."}]$ex$::jsonb),
  ('49965686-6d82-542f-9855-8b1bc14db7a5'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Cueillez, cueillez… et l’animal-poète","competence":"analyser-texte","situation":"Deux textes pour comprendre le sonnet et l’ode de la Pléiade : la dernière strophe d’une ode de Ronsard, et le premier quatrain d’un poème imaginaire dans le goût de Pétrarque.","documents":[{"id":"ode","type":"texte","genre":"poeme","titre":"Dernière strophe de « Mignonne, allons voir si la rose »","blocs":["Donc, si vous me croyez, mignonne,","Tandis que votre âge fleuronne","En sa plus verte nouveauté,","Cueillez, cueillez votre jeunesse :","Comme à cette fleur, la vieillesse","Fera ternir votre beauté."],"source":"Pierre de Ronsard, Odes (XVIe siècle), orthographe modernisée"},{"id":"cerf","type":"texte","genre":"poeme","titre":"Un poème « à la manière de Pétrarque »","blocs":["Cerf blessé, je me traîne au bord de la forêt ;","Ma dame est cette biche que nul ne peut saisir ;","Oiseau pris à sa voix, je chante en ma prison :","Mon mal est mon seul bien, ma peine mon plaisir."],"source":"Vers écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot que Ronsard répète pour inviter la jeune femme à profiter du présent.","aide":"C’est un verbe à l’impératif, au vers 4.","type":"zone","document":"ode","multiple":true},{"enonce":"Comment appelle-t-on, en deux mots latins, ce thème hérité d’Horace : « profite du présent » ?","aide":"Cueille le jour…","type":"texte","placeholder":"deux mots latins"},{"enonce":"Dans le poème imaginaire, relie chaque image animale à ce qu’elle dit.","aide":"Relis chaque vers : que ressent le poète, et que fait la dame ?","type":"association","gauche":[{"id":"g0","texte":"Le cerf blessé"},{"id":"g1","texte":"La biche"},{"id":"g2","texte":"L’oiseau pris à sa voix"}],"droite":[{"id":"d0","texte":"La douleur du désir"},{"id":"d1","texte":"La dépendance"},{"id":"d2","texte":"La dame inaccessible"}]},{"enonce":"Dans ce poème, que représente l’animal ?","aide":"Le poète est-il vraiment un cerf ?","type":"choix","options":[{"id":"a","texte":"Un simple décor qui n’a aucun rapport avec les sentiments du poète"},{"id":"b","texte":"Un souvenir précis de chasse qui a marqué l’enfance du poète"},{"id":"c","texte":"Un véhicule de la métaphore, pour dire ce que le poète ne peut dire en propre"},{"id":"d","texte":"Une bête réelle que le poète a rencontrée pendant une promenade en forêt"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m17"]},"explication":"**Cueillez, cueillez** : l’impératif répété traduit l’urgence du **carpe diem**."},{"cle":{"type":"texte","acceptes":["carpe diem"]},"affichage":"carpe diem","explication":"Le thème est le **carpe diem**, « cueille le jour » : la beauté passe, il faut en jouir."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Le **cerf blessé** dit la **douleur du désir** ; la **biche**, la dame **inaccessible** ; l’oiseau en cage, la **dépendance**. Ces images viennent de Pétrarque."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’animal n’est pas une bête réelle : c’est un **véhicule de la métaphore**, qui permet de dire ce que le poète ne peut pas dire en propre."}]$ex$::jsonb),
  ('c12fd49c-b21f-5ec5-86b4-f1f9095c0b01'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une exposition sur le lion","competence":"analyser-document","situation":"Le CDI prépare une exposition : « Le lion, un animal à plusieurs visages ». Voici l’affiche, avec les œuvres exposées.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Le lion dans les livres","sousTitre":"De la Bible à aujourd’hui","emoji":"🦁","teinte":"ambre","lignes":[{"texte":"Ésope","valeur":"La part du lion","id":"z1"},{"texte":"Bestiaire médiéval","valeur":"Le lion, figure du Christ","id":"z2"},{"texte":"Chrétien de Troyes","valeur":"Le Chevalier au lion","id":"z3"},{"texte":"Roman de Renart","valeur":"Noble, roi faible et partial","id":"z4"},{"texte":"La Fontaine","valeur":"Le Lion et le Rat","id":"z5"},{"texte":"Joseph Kessel","valeur":"Le Lion (roman)","id":"z6"}],"pied":"CDI — du lundi au vendredi"}],"questions":[{"enonce":"Touche l’œuvre où un lion devient le compagnon fidèle du héros, Yvain.","aide":"Cherche le titre qui contient le mot « lion » et un chevalier.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la ligne où le lion est un roi faible et partial.","aide":"Il porte un nom qui sonne comme un titre.","type":"zone","document":"affiche","multiple":false},{"enonce":"Complète : le lion n’est ni bon ni mauvais, il est un ___ ; et un signe se lit dans son ___.","aide":"L’exposition montre des lions très différents : qu’est-ce qui explique leur sens ?","type":"trous","segments":["Le lion est un ",0," ; et un signe se lit dans son ",1,"."],"banque":["signe","contexte","décor","modèle"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"*Le Chevalier au lion* de **Chrétien de Troyes** : le lion est le **compagnon fidèle** d’Yvain."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Dans le *Roman de Renart*, le lion s’appelle **Noble** : c’est un roi faible et partial."},{"cle":{"type":"trous","trous":[["signe"],["contexte"]]},"affichage":"signe · contexte","explication":"Le lion est un **signe** : sa valeur change selon l’époque, le genre et l’intention, donc il se lit dans son **contexte**."}]$ex$::jsonb),
  ('c12fd49c-b21f-5ec5-86b4-f1f9095c0b01'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le lion de La Fontaine, un fort qui peut tomber","competence":"analyser-texte","situation":"Deux fables de La Fontaine mettent en scène un lion : dans l’une, la morale ; dans l’autre, un partage. Lis le début de la première et le résumé de la seconde, rédigé pour l’exercice.","documents":[{"id":"rat","type":"texte","genre":"poeme","titre":"Le Lion et le Rat","blocs":["Il faut, autant qu’on peut, obliger tout le monde :","On a souvent besoin d’un plus petit que soi."],"source":"Jean de La Fontaine, Fables, II, 11 (1668)"},{"id":"partage","type":"texte","genre":"recit","titre":"La Génisse, la Chèvre et la Brebis en société avec le Lion","blocs":["Une génisse, une chèvre et une brebis s’associent à un lion. Elles prennent un cerf et le lion le coupe en quatre parts.","La première lui revient, dit-il, parce qu’il s’appelle Lion. La deuxième lui est due par droit. La troisième lui revient parce qu’il est le plus vaillant. Quant à la quatrième, gare à qui y touchera."],"source":"Résumé rédigé pour l’exercice, d’après La Fontaine"}],"questions":[{"enonce":"Dans la morale, touche l’adjectif qui désigne celui dont on peut avoir besoin.","aide":"La morale dit qu’on a besoin d’un plus… que soi.","type":"zone","document":"rat","multiple":false},{"enonce":"Dans le résumé de la seconde fable, relie chaque part à la raison que le lion en donne.","aide":"Relis le deuxième paragraphe, phrase par phrase.","type":"association","gauche":[{"id":"g0","texte":"Première part"},{"id":"g1","texte":"Deuxième part"},{"id":"g2","texte":"Troisième part"},{"id":"g3","texte":"Quatrième part"}],"droite":[{"id":"d0","texte":"Parce qu’il est le plus vaillant"},{"id":"d1","texte":"Gare à qui y touchera"},{"id":"d2","texte":"Par droit"},{"id":"d3","texte":"Parce qu’il s’appelle Lion"}]},{"enonce":"Que montre cette seconde fable ?","aide":"Qui décide du partage ? Les associés ou le lion ?","type":"choix","options":[{"id":"a","texte":"Le partage équitable d’une proie entre associés"},{"id":"b","texte":"La loi du plus fort déguisée en contrat"},{"id":"c","texte":"La vaillance d’un chef qui protège son troupeau"},{"id":"d","texte":"La reconnaissance du puissant envers les petits"}],"multiple":false},{"enonce":"Range chaque situation : le fort écrase le faible, ou le rapport de force se retourne.","aide":"Une fable est celle du partage, l’autre celle du service rendu.","type":"categories","categories":[{"id":"c0","texte":"Le fort écrase le faible"},{"id":"c1","texte":"Le rapport de force se retourne"}],"items":[{"id":"i0","texte":"Le lion garde les quatre parts du cerf"},{"id":"i1","texte":"Les trois associées repartent sans rien"},{"id":"i2","texte":"Le Rat délivre le Lion pris au piège"},{"id":"i3","texte":"Un petit sauve un puissant"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"La morale est : « On a souvent besoin d’un plus **petit** que soi » : le rapport de force peut se retourner."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"Le lion se sert **quatre fois** en invoquant des raisons de plus en plus menaçantes : le nom, le droit, la vaillance, puis la menace."},{"cle":{"type":"choix","ids":["b"]},"explication":"La société est un **contrat de façade** : c’est le plus fort qui garde tout. La fable montre **la loi du plus fort déguisée en contrat**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Dans la fable du partage, le fort **écrase** le faible ; dans *Le Lion et le Rat*, le petit **sauve** le puissant."}]$ex$::jsonb),
  ('c12fd49c-b21f-5ec5-86b4-f1f9095c0b01'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Trois lions, trois sens","competence":"analyser-document","situation":"Trois paragraphes présentent trois lions très différents : un bestiaire, un roman médiéval, une publicité imaginée. Les trois disent-ils la même chose ?","documents":[{"id":"lions","type":"texte","genre":"source","titre":"Trois lions","blocs":["Le lion efface ses traces avec sa queue, dort les yeux ouverts et, au troisième jour, ranime ses petits : autant de signes qui le rapprochent du Christ.","Le roi Noble, un lion, rend la justice selon l’humeur de ceux qui le flattent : il se laisse mener, et sa cour en profite.","Sur l’affiche d’une marque de voitures, un lion bondit au-dessus de la route : « Soyez le plus fort »."],"source":"Textes écrits pour l’exercice : le premier d’après les bestiaires médiévaux, le deuxième d’après le Roman de Renart, le troisième imaginé"}],"questions":[{"enonce":"Relie chaque paragraphe à ce que le lion y représente.","aide":"Quel texte vient d’un bestiaire ? Lequel du Roman de Renart ? Lequel d’une marque ?","type":"association","gauche":[{"id":"g0","texte":"Paragraphe 1"},{"id":"g1","texte":"Paragraphe 2"},{"id":"g2","texte":"Paragraphe 3"}],"droite":[{"id":"d0","texte":"Un roi faible et partial"},{"id":"d1","texte":"Un emblème commercial"},{"id":"d2","texte":"Une figure du Christ"}]},{"enonce":"Dans le paragraphe 1, touche les trois mots qui disent les traits du lion qui en font un symbole du Christ.","aide":"Cherche trois verbes ou adjectifs qui décrivent ce que fait le lion.","type":"zone","document":"lions","multiple":true},{"enonce":"Dans la publicité, touche le mot qui emprunte au lion sa qualité.","aide":"La marque veut transmettre une image de puissance.","type":"zone","document":"lions","multiple":false},{"enonce":"Que prouve le rapprochement de ces trois lions ?","aide":"Les trois lions disent-ils la même chose ?","type":"choix","options":[{"id":"a","texte":"Le lion signifie toujours la même chose dans toute la littérature"},{"id":"b","texte":"Les auteurs médiévaux ne connaissaient pas les animaux réels"},{"id":"c","texte":"Seule la publicité sait donner au lion un sens contemporain"},{"id":"d","texte":"Le sens d’un motif dépend de l’époque, du genre et de l’auteur"}],"multiple":false},{"enonce":"Complète : le motif du lion est ___ (on le retrouve partout) et ___ (il change de valeur).","aide":"Un mot dit « partout », l’autre « plusieurs sens ».","type":"trous","segments":["Le motif du lion est ",0," (on le retrouve partout) et ",1," (il change de valeur)."],"banque":["pluriel","universel","fixe","rare"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Paragraphe 1 : le **bestiaire**, le lion est une **figure du Christ** ; paragraphe 2 : le **Roman de Renart**, un **roi faible et partial** ; paragraphe 3 : un **emblème commercial**."},{"cle":{"type":"zone","ids":["m2","m11","m16"]},"explication":"Il **efface** ses traces, dort les yeux **ouverts**, **ranime** ses petits au troisième jour : ce sont les vertus que le bestiaire lit comme des signes du Christ."},{"cle":{"type":"zone","ids":["m70"]},"explication":"La marque emprunte au lion sa **force** : le lion est devenu un **emblème commercial**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le motif est **universel** (on le retrouve partout) et **pluriel** : il change de valeur selon l’époque, le genre et l’intention de l’auteur."},{"cle":{"type":"trous","trous":[["universel"],["pluriel"]]},"affichage":"universel · pluriel","explication":"Il est **universel** et **pluriel**."}]$ex$::jsonb),
  ('0c8cd730-90f7-5fc4-be33-6cf606139a47'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un fromage et une leçon","competence":"analyser-texte","situation":"Mélina étudie une fable célèbre de La Fontaine. Elle veut retrouver les deux temps de la fable et ce que l’auteur cache derrière deux animaux.","documents":[{"id":"fable","type":"texte","genre":"poeme","titre":"Le Corbeau et le Renard","blocs":["Maître Corbeau, sur un arbre perché,","Tenait en son bec un fromage.","Maître Renard, par l’odeur alléché,","Lui tint à peu près ce langage :","","(…)","","Apprenez que tout flatteur","Vit aux dépens de celui qui l’écoute :","Cette leçon vaut bien un fromage, sans doute."],"source":"Jean de La Fontaine, Fables, I, 2 (1668) : début et morale"}],"questions":[{"enonce":"Touche les deux animaux de la fable.","aide":"Ils portent un titre de politesse, « Maître ».","type":"zone","document":"fable","multiple":true},{"enonce":"Dans la morale, touche le mot qui nomme le défaut dénoncé.","aide":"Celui qui dit des compliments pour obtenir quelque chose.","type":"zone","document":"fable","multiple":false},{"enonce":"Relie chaque élément de la fable à son rôle.","aide":"Une fable se fait en deux temps ; les animaux, eux, sont un masque.","type":"association","gauche":[{"id":"g0","texte":"Le récit"},{"id":"g1","texte":"La morale"},{"id":"g2","texte":"L’animalisation"}],"droite":[{"id":"d0","texte":"La leçon, ici donnée en fin de fable"},{"id":"d1","texte":"La situation, la rencontre, l’issue"},{"id":"d2","texte":"Elle plaît et elle protège l’auteur"}]},{"enonce":"Pourquoi La Fontaine parle-t-il d’un renard et pas d’un courtisan ?","aide":"Que peut-on dire d’un loup qu’on n’oserait pas dire d’un ministre ?","type":"choix","options":[{"id":"a","texte":"Il ne connaissait aucun courtisan à la cour du roi de France"},{"id":"b","texte":"Il veut seulement raconter une histoire d’animaux aux enfants"},{"id":"c","texte":"Il préfère que les animaux parlent un langage plus savant"},{"id":"d","texte":"La scène est plaisante et l’auteur ne risque rien à critiquer"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m13"]},"explication":"Le **Corbeau** et le **Renard** : deux animaux qui jouent une petite scène humaine."},{"cle":{"type":"zone","ids":["m28"]},"explication":"La morale dénonce le **flatteur**, qui vit aux dépens de celui qui l’écoute."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"La fable a deux temps, le **récit** puis la **morale** ; l’**animalisation** plaît au lecteur et protège l’auteur."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’animalisation produit un **double effet** : elle **plaît** (la scène est drôle, donc lue) et elle **protège** l’auteur."}]$ex$::jsonb),
  ('0c8cd730-90f7-5fc4-be33-6cf606139a47'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Au pays de Bonlieu, la justice est parfaite","competence":"analyser-texte","situation":"Voici un petit conte écrit pour l’exercice, à la manière des Lumières, et deux vers de La Fontaine écrits un siècle plus tôt. Qu’ont-ils en commun ?","documents":[{"id":"conte","type":"texte","genre":"recit","titre":"Le tribunal de Bonlieu","blocs":["Au pays de Bonlieu, le grand juge Plumeau rendait la justice avec une impartialité exemplaire : il condamnait toujours le pauvre, ce qui épargnait au tribunal la fatigue de réfléchir.","— Notre loi est parfaite, expliquait-il, puisque personne n’a jamais osé la contester sans être aussitôt puni.","Les habitants, qui trouvaient cela admirable, remerciaient chaque matin le tribunal de sa bonté."],"source":"Texte écrit pour l’exercice, à la manière du conte philosophique"},{"id":"vers","type":"texte","genre":"poeme","titre":"Les Animaux malades de la peste","blocs":["Selon que vous serez puissant ou misérable,","Les jugements de cour vous rendront blanc ou noir."],"source":"Jean de La Fontaine, Fables, VII, 1 (1678)"}],"questions":[{"enonce":"Dans le conte, touche les deux mots qui louent ce que l’auteur condamne : c’est l’ironie.","aide":"Cherche les adjectifs flatteurs qui décrivent la justice de Plumeau.","type":"zone","document":"conte","multiple":true},{"enonce":"Chez La Fontaine, touche les deux mots qui s’opposent pour dire l’inégalité devant la justice.","aide":"Un homme fort, un homme faible.","type":"zone","document":"vers","multiple":true},{"enonce":"Quel point commun entre le conte et la fable ?","aide":"Que veulent faire voir les deux auteurs, et où détournent-ils le regard ?","type":"choix","options":[{"id":"a","texte":"Ils condamnent les animaux et les pauvres qui refusent de se taire"},{"id":"b","texte":"Ils dénoncent une justice inégale par un détour : un pays imaginaire ou des animaux"},{"id":"c","texte":"Ils défendent tous deux l’ancien régime contre ceux qui le critiquent"},{"id":"d","texte":"Ils racontent la vraie vie d’un juge qui a existé à la cour du roi"}],"multiple":false},{"enonce":"Relie chaque forme du XVIIIe siècle à un exemple.","aide":"Le premier est un récit, le deuxième classe les mots, le troisième est une correspondance imaginée.","type":"association","gauche":[{"id":"g0","texte":"Le conte philosophique"},{"id":"g1","texte":"Le dictionnaire"},{"id":"g2","texte":"La lettre fictive"}],"droite":[{"id":"d0","texte":"Le Dictionnaire philosophique"},{"id":"d1","texte":"Les Lettres persanes de Montesquieu"},{"id":"d2","texte":"Candide"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m32"]},"explication":"**Exemplaire** et **parfaite** louent une justice absurde : l’auteur dit le contraire de ce qu’il pense, c’est l’**ironie**."},{"cle":{"type":"zone","ids":["m4","m6"]},"explication":"**Puissant** et **misérable** : la justice dépend du rang de celui qu’on juge."},{"cle":{"type":"choix","ids":["b"]},"explication":"Fable et conte **détournent le regard** (animaux, pays imaginaire) pour faire voir le scandale de chez soi : une **justice inégale**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"*Candide* est un **conte philosophique** ; le *Dictionnaire philosophique* est un **dictionnaire** ; les *Lettres persanes* sont une **lettre fictive**."}]$ex$::jsonb),
  ('0c8cd730-90f7-5fc4-be33-6cf606139a47'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un Persan s’étonne de Paris","competence":"analyser-document","situation":"Un voyageur imaginaire écrit à un ami : texte inventé pour l’exercice, à la manière des Lettres persanes. Dans la même veine, observe aussi un tableau des combats du siècle.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Rica à Usbek","blocs":["Cher Usbek,","Les Français ont ici un étrange usage : le pauvre qui vole un pain est enchaîné, mais le riche qui vole un village est invité à dîner.","Je crois que cela s’appelle la justice ; et nous autres étrangers la trouvons bizarre, tandis que les habitants s’y sont habitués."],"source":"Texte écrit pour l’exercice, à la manière des Lettres persanes"},{"id":"combats","type":"tableau","titre":"Quelques combats des Lumières","colonnes":["Ce que le siècle combat","Un exemple"],"lignes":[["L’esclavage","Le nègre de Surinam, dans Candide"],["Les erreurs judiciaires","L’affaire Calas, combattue par Voltaire"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots par lesquels l’étranger feint de s’étonner.","aide":"Il trouve ces usages bien curieux.","type":"zone","document":"lettre","multiple":true},{"enonce":"Quelle stratégie cette lettre partage-t-elle avec la fable ?","aide":"La fable parle d’un animal ; ici, qui parle ?","type":"choix","options":[{"id":"a","texte":"Éviter toute morale et laisser le lecteur seul"},{"id":"b","texte":"Écrire en vers pour se faire mieux retenir"},{"id":"c","texte":"Appuyer la démonstration sur des chiffres exacts"},{"id":"d","texte":"Détourner le regard vers un ailleurs, ici un étranger"}],"multiple":false},{"enonce":"Range chaque personnage selon le « masque » qui permet de critiquer.","aide":"Qui est une bête qui parle ? Qui découvre le monde avec un œil neuf ?","type":"categories","categories":[{"id":"c0","texte":"Un animal"},{"id":"c1","texte":"Un naïf ou un étranger"}],"items":[{"id":"i0","texte":"Le Loup et l’Agneau"},{"id":"i1","texte":"Rica, dans les Lettres persanes"},{"id":"i2","texte":"Candide"},{"id":"i3","texte":"Le Lion de La Fontaine"}]},{"enonce":"Dans le tableau, touche la case qui nomme l’affaire judiciaire que Voltaire a combattue.","aide":"Cherche la ligne « Les erreurs judiciaires ».","type":"zone","document":"combats","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m42"]},"explication":"**Étrange** et **bizarre** : le regard naïf d’un étranger fait voir le scandale de chez soi."},{"cle":{"type":"choix","ids":["d"]},"explication":"Toutes ces formes détournent le regard vers un **ailleurs** — animal, naïf, **étranger** — pour faire voir le scandale de chez soi."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Dans la fable, le masque est un **animal** ; dans les Lettres persanes ou *Candide*, c’est un **étranger** ou un **naïf**."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Voltaire a combattu les erreurs judiciaires dans l’**affaire Calas**."}]$ex$::jsonb),
  ('1f740378-bc6a-576a-b8e3-f86e71be993f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Convaincre, persuader, délibérer","competence":"argumenter","situation":"Camille prépare un dossier sur la lecture. Elle a rédigé trois paragraphes qui n’ont pas la même visée : à toi de les distinguer.","documents":[{"id":"trois","type":"texte","genre":"article","titre":"Trois paragraphes sur la lecture","blocs":["Dans la classe de Camille, les élèves qui lisent vingt minutes par jour ont progressé deux fois plus vite en français. Donc, la lecture quotidienne améliore les résultats.","Imagine un soir d’hiver, un livre ouvert, une lampe qui éclaire la page : n’as-tu jamais rêvé de ce moment-là ?","D’un côté, la lecture prend du temps aux écrans ; de l’autre, elle enrichit le vocabulaire. Pesons les deux avant de conclure."],"source":"Textes écrits pour l’exercice"}],"questions":[{"enonce":"Relie chaque paragraphe à sa visée.","aide":"Un paragraphe aligne un fait et une conséquence, un autre peint une image, un dernier hésite.","type":"association","gauche":[{"id":"g0","texte":"Paragraphe 1"},{"id":"g1","texte":"Paragraphe 2"},{"id":"g2","texte":"Paragraphe 3"}],"droite":[{"id":"d0","texte":"Il délibère : il pèse plusieurs thèses"},{"id":"d1","texte":"Il persuade : il touche les émotions"},{"id":"d2","texte":"Il convainc : il s’adresse à la raison"}]},{"enonce":"Dans le paragraphe 1, touche le connecteur logique qui introduit la conclusion.","aide":"Un petit mot qui relie la preuve à sa conséquence.","type":"zone","document":"trois","multiple":false},{"enonce":"Dans le paragraphe 3, touche le mot qui annonce qu’on va comparer les deux thèses avant de trancher.","aide":"Un verbe à l’impératif, à la première personne du pluriel.","type":"zone","document":"trois","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"1 : **convaincre** (une preuve, une conclusion) ; 2 : **persuader** (une image, une émotion) ; 3 : **délibérer** (peser avant de trancher)."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**Donc** est un connecteur logique : il organise le raisonnement."},{"cle":{"type":"zone","ids":["m66"]},"explication":"**Pesons** : délibérer, c’est peser plusieurs thèses avant de trancher."}]$ex$::jsonb),
  ('1f740378-bc6a-576a-b8e3-f86e71be993f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"13 janvier 1898, une une qui fait date","competence":"analyser-document","situation":"Dans le journal *L’Aurore*, Zola publie un texte qui va bouleverser la France. Voici une frise de repères et deux phrases de l’article.","documents":[{"id":"frise","type":"frise","titre":"Presse et littérature d’idées","debut":1880,"fin":1950,"pas":10,"evenements":[{"id":"z1","date":1881,"nom":"Loi sur la presse"},{"id":"z2","date":1898,"nom":"J’accuse…!"},{"id":"z3","date":1949,"nom":"Le Deuxième Sexe"}]},{"id":"zola","type":"texte","genre":"source","titre":"Deux phrases de « J’accuse…! »","blocs":["Mon devoir est de parler, je ne veux pas être complice.","La vérité est en marche, et rien ne l’arrêtera."],"source":"Émile Zola, « J’accuse…! », L’Aurore, 13 janvier 1898"}],"questions":[{"enonce":"Touche l’événement qui garantit la liberté de la presse.","aide":"C’est une loi de 1881.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent cette loi de la publication de « J’accuse…! » ?","aide":"Soustrais 1881 de 1898.","type":"nombre","unite":"ans"},{"enonce":"Dans la première phrase, touche le mot par lequel Zola refuse d’être coupable de son silence.","aide":"Celui qui se tait participe à la faute des autres.","type":"zone","document":"zola","multiple":false},{"enonce":"Dans « La vérité est en marche, et rien ne l’arrêtera », la visée dominante est de…","aide":"Une vérité qui « marche » : est-ce un raisonnement ou une image ?","type":"choix","options":[{"id":"a","texte":"Convaincre uniquement avec des chiffres et des preuves"},{"id":"b","texte":"Informer sans prendre parti dans l’affaire Dreyfus"},{"id":"c","texte":"Délibérer, en pesant calmement plusieurs thèses"},{"id":"d","texte":"Persuader, par une image forte qui touche l’émotion"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La **loi du 29 juillet 1881** garantit la liberté de la presse."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17 ans","explication":"1898 − 1881 = **17** ans."},{"cle":{"type":"zone","ids":["m10"]},"explication":"Zola refuse d’être **complice** : il a le devoir de parler."},{"cle":{"type":"choix","ids":["d"]},"explication":"La **vérité qui marche** est une image frappante : la visée est de **persuader**, de toucher l’émotion, en plus de convaincre."}]$ex$::jsonb),
