nouveaux financements"},{"id":"g2","texte":"L’abondance d’images"}],"droite":[{"id":"d0","texte":"Que valent-elles comme preuve ?"},{"id":"d1","texte":"Qui finance ?"},{"id":"d2","texte":"Comment vérifier ?"}]},{"enonce":"Range chaque attitude : bon ou mauvais réflexe face à une information.","aide":"Quel réflexe vérifie ? Lequel se laisse emporter ?","type":"categories","categories":[{"id":"c0","texte":"Bon réflexe"},{"id":"c1","texte":"Mauvais réflexe"}],"items":[{"id":"i0","texte":"Chercher le document d’origine"},{"id":"i1","texte":"Dater la photo par une recherche d’image inversée"},{"id":"i2","texte":"Croire une info parce qu’elle a été vue 40 000 fois"},{"id":"i3","texte":"Partager parce que le titre fait peur"}]}]}$ex$::jsonb,
