  ('a629bed4-b40c-553e-bf7d-4c9a84099664'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une brève sur le gymnase fermé","competence":"analyser-texte","situation":"Le journal du lycée publie cette brève. Un bon journaliste y répond aux questions de base : qui, quoi, quand, où, pourquoi.","documents":[{"id":"breve","type":"texte","genre":"article","titre":"Gymnase fermé","blocs":["Le gymnase du lycée des Tilleuls, à Dijon, a été fermé hier soir après une fuite d’eau. Aucun blessé n’est à signaler.","La proviseure précise que la réouverture est prévue lundi, car les réparations demandent trois jours."],"source":"Brève écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui répond à la question « où ? ».","aide":"Cherche un nom de ville.","type":"zone","document":"breve","multiple":false},{"enonce":"Touche les deux mots qui répondent à la question « quand ? ».","aide":"Un jour et un moment de la journée.","type":"zone","document":"breve","multiple":true},{"enonce":"Touche le mot qui répond à la question « pourquoi ? ».","aide":"Quelle est la cause de la fermeture ?","type":"zone","document":"breve","multiple":false},{"enonce":"Pourquoi cette brève donne-t-elle l’essentiel dès la première phrase ?","aide":"Que se passe-t-il si le journal manque de place et coupe la fin ?","type":"choix","options":[{"id":"a","texte":"Les lecteurs n’aiment que les phrases courtes et sans détail"},{"id":"b","texte":"Le journaliste ne connaît pas encore le reste des informations"},{"id":"c","texte":"La première phrase est toujours la plus drôle de l’article"},{"id":"d","texte":"C’est la pyramide inversée : on peut couper la fin sans perdre l’essentiel"}],"multiple":false}]}$ex$::jsonb,
