  ('6ce74e29-30fe-5eda-8520-97b1bde07a25'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une lettre de 1836 sur un journal moins cher","competence":"analyser-texte","situation":"En 1836, un lecteur écrit à son ami pour lui raconter une grande nouveauté : un journal qui coûte deux fois moins cher. Les prix de cette lettre sont imaginés pour l’exercice.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre à un ami","blocs":["Paris, le 1er juillet 1836","Cher Auguste,","Tu ne devineras jamais ! Un nouveau journal, *La Presse*, coûte deux fois moins cher que les autres : monsieur de Girardin le finance en vendant de la publicité aux commerçants. Mon abonnement me coûtait 80 francs par an ; il me revient désormais à la moitié.","Je crois que tout le monde va s’y mettre."],"source":"Lettre imaginée pour l’exercice (prix inventés)"}],"questions":[{"enonce":"Touche le mot qui explique comment le journal peut coûter moins cher.","aide":"Que vend le journal aux commerçants, en plus des numéros ?","type":"zone","document":"lettre","multiple":false},{"enonce":"Combien l’abonnement coûte-t-il désormais, en francs par an ?","aide":"Le prix a été divisé par deux.","type":"nombre","unite":"francs"},{"enonce":"Complète : Girardin finance le journal par la ___ pour en baisser le ___.","aide":"Relis la lettre : d’où vient l’argent, et que devient le prix ?","type":"trous","segments":["Girardin finance le journal par la ",0," pour en baisser le ",1,"."],"banque":["tirage","prix","censure","publicité"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m33"]},"explication":"Girardin finance le journal par la **publicité** : c’est ce qui lui permet de baisser le prix."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 francs","explication":"80 ÷ 2 = **40** francs : Girardin divise par deux le prix de *La Presse* en 1836."},{"cle":{"type":"trous","trous":[["publicite"],["prix"]]},"affichage":"publicité · prix","explication":"Par la **publicité** : le **prix** peut baisser, donc le journal touche plus de lecteurs."}]$ex$::jsonb),
  ('6ce74e29-30fe-5eda-8520-97b1bde07a25'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Épisode 12 : le suspense fait vendre","competence":"analyser-document","situation":"Pour fidéliser ses lecteurs, un journal publie un roman en épisodes au bas de la une. Voici un épisode inventé, à la manière d’Eugène Sue, et la liste des grands feuilletons.","documents":[{"id":"episode","type":"texte","genre":"recit","titre":"Épisode 12","blocs":["La nuit tombait sur le port. Marianne, la jeune orpheline, serra contre elle le médaillon de sa mère ; derrière elle, le traître Grimaud, drapé dans son manteau noir, avançait sans bruit.","Soudain, une main se posa sur son épaule… À suivre."],"source":"Texte écrit pour l’exercice, à la manière d’un roman-feuilleton"},{"id":"liste","type":"tableau","titre":"Quelques grands feuilletons","colonnes":["Auteur","Feuilleton"],"lignes":[["Eugène Sue","Les Mystères de Paris"],["Alexandre Dumas","Les Trois Mousquetaires"],["Alexandre Dumas","Le Comte de Monte-Cristo"]],"enteteLignes":true}],"questions":[{"enonce":"Dans le tableau, touche le feuilleton d’Eugène Sue.","aide":"Cherche la ligne du premier auteur.","type":"zone","document":"liste","multiple":false},{"enonce":"Dans l’épisode, touche les deux mots qui donnent envie d’acheter le numéro suivant.","aide":"Ils sont à la toute fin du texte.","type":"zone","document":"episode","multiple":true},{"enonce":"Touche les deux mots qui rangent les personnages dans un type, facile à reconnaître.","aide":"L’un est une victime, l’autre un méchant.","type":"zone","document":"episode","multiple":true},{"enonce":"Relie chaque contrainte du feuilleton à son effet sur l’écriture.","aide":"Le journal paraît tous les jours : qu’est-ce que cela exige de l’auteur ?","type":"association","gauche":[{"id":"g0","texte":"Le suspense en fin d’épisode"},{"id":"g1","texte":"La parution régulière"},{"id":"g2","texte":"Un public large"}],"droite":[{"id":"d0","texte":"Des rebondissements fréquents"},{"id":"d1","texte":"Des chapitres courts"},{"id":"d2","texte":"Des personnages typés"}]}]}$