  ('e16927b4-a7b2-5d99-81c8-3cee14bec333'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Écrire l’absence depuis un rocher","competence":"analyser-texte","situation":"Voici un poème écrit pour l’exercice, à la manière de Hugo en exil, et un tableau à compléter sur les procédés qui disent l’absence.","documents":[{"id":"poeme","type":"texte","genre":"poeme","titre":"Depuis l’île","blocs":["Ô France, ô mon pays, que je ne vois plus,","Je t’appelle du roc que l’Océan assiège ;","Ici, l’île, le vent, les vagues et le sel ;","Là-bas, tes quais, tes toits, tes places, tes drapeaux.","La houle me répond de sa voix de tonnerre ;","Et j’attends, et j’attends que le jour te revienne."],"source":"Vers écrits pour l’exercice, à la manière de Victor Hugo"},{"id":"procedes","type":"tableau","titre":"Dire l’absence","colonnes":["Le procédé","Ce qu’il produit"],"lignes":[["L’antithèse entre ici et là-bas","?"],["Le champ lexical de la mer et de l’île","?"],["L’apostrophe au pays perdu","?"],["La personnification de l’Océan","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le nom du pays auquel le poète s’adresse directement (l’apostrophe).","aide":"Au vers 1, il appelle quelqu’un comme dans une lettre.","type":"zone","document":"poeme","multiple":false},{"enonce":"Touche les quatre mots qui disent la mer.","aide":"Cherche une grande étendue, ses mouvements et son goût.","type":"zone","document":"poeme","multiple":true},{"enonce":"Complète le tableau : relie chaque procédé à ce qu’il produit.","aide":"Pense à ce que chaque procédé fait voir ou entendre dans les vers.","type":"association","gauche":[{"id":"g0","texte":"L’antithèse ici / là-bas"},{"id":"g1","texte":"Le champ lexical de la mer et de l’île"},{"id":"g2","texte":"L’apostrophe au pays perdu"},{"id":"g3","texte":"La personnification de l’Océan"}],"droite":[{"id":"d0","texte":"L’enfermement et l’horizon"},{"id":"d1","texte":"Des forces qui répondent"},{"id":"d2","texte":"Le partage du monde en deux"},{"id":"d3","texte":"Le pays devient un interlocuteur"}]},{"enonce":"« La houle me répond de sa voix de tonnerre » : de quel procédé s’agit-il ?","aide":"La houle parle et répond : à qui ressemble-t-elle ?","type":"choix","options":[{"id":"a","texte":"Un oxymore entre calme et colère"},{"id":"b","texte":"Une allitération du son [t]"},{"id":"c","texte":"Une litote qui atténue la menace"},{"id":"d","texte":"Une personnification de la mer"}],"multiple":false},{"enonce":"Que devient l’exil, chez Hugo, malgré l’absence ?","aide":"Pense aux livres qu’il publie et à son autorité morale.","type":"choix","options":[{"id":"a","texte":"Une longue pause avant de reprendre son métier de journaliste"},{"id":"b","texte":"Une manière de rester : absent du territoire, il est omniprésent dans les esprits"},{"id":"c","texte":"Une punition subie qui l’empêche d’écrire et de publier ses livres"},{"id":"d","texte":"Un repos loin de la politique et du bruit de la France d’alors"}],"multiple":false}]}$ex$::jsonb,
